INSERT INTO `news_posts` (`id`, `title`, `slug`, `excerpt`, `content`, `is_published`, `published_at`, `created_at`, `updated_at`, `image_url`) VALUES
(1, 'Harvest opens in Rwamagana', 'harvest-opens-in-rwamagana', 'The first cherries of the season are arriving at Karenge. Here is how we prepare the mill, the beds, and the teams.', '<p>The main harvest has opened across our partner hills in Rwamagana. Farmers are delivering ripe red cherries each morning, and the station team is sorting, floating, and preparing fermentation tanks for the first washed lots of the year.</p><p>This season we are focusing on tighter cherry selection, cleaner water management, and more frequent cupping so every lot can be traced from the farm to the drying bed.</p>', 0, '2026-03-12 09:00:00', '2026-09-23 13:10:11', '2026-09-24 07:33:47', NULL),
(2, 'A dedicated lot from 156 women farmers', 'women-farmers-lot-2026', 'Our women’s association is delivering a separated lot this season — with its own processing track and cupping table.', '<p>GMAC works with an association of 156 women farmers. This year their cherries are kept separate from the main blend so buyers can source a fully traceable women’s lot.</p><p>The project is about quality and income: better cherry prices, shared training, and a cup that tells a clear story from origin.</p>', 0, '2026-04-02 09:00:00', '2026-09-23 13:10:11', '2026-09-24 07:33:47', NULL),
(3, 'Cupping notes from Karenge', 'cupping-notes-from-karenge', 'Early washed tables are showing citrus, black tea, and a sweet red-apple finish.', '<p>Our quality team has started the first formal cuppings of the season. The washed Bourbon tables are bright and precise — citrus oil, black tea, and a clean sweetness that holds as the cup cools.</p><p>Honey and natural experiments will follow later in the harvest. Sample requests are open for importers and roasters.</p>', 0, '2026-05-18 09:00:00', '2026-09-23 13:10:11', '2026-09-24 07:33:47', NULL),
(4, 'GMAC at the European Coffee Exhibition: showcasing Ntwali Coffee', 'gmac-european-coffee-exhibition-ntwali', 'GMAC took Rwandan coffee to a European exhibition, introducing Ntwali to roasters, distributors, and buyers.', '<p>GMAC joined a European coffee exhibition to put Rwandan coffee — and our Ntwali brand — in front of roasters, distributors, and buyers. The event was a working room as much as a showcase: conversations about origin, process, and long-term supply.</p><p>We presented lots from Karenge and Gasange and spoke about how cherries move from farm to cupping table. The aim was simple: a clear story from Rwanda, and contacts that can become regular trade.</p>', 0, '2026-03-24 09:00:00', '2026-09-23 19:42:22', '2026-09-24 07:33:47', NULL),
(5, 'Warm up this cold season with Ntwali Coffee', 'warm-up-with-ntwali-coffee', 'Ntwali is GMAC’s roasted coffee — a cup from origin for the colder months.', '<p>Ntwali is GMAC’s roasted coffee: Arabica Bourbon from our Eastern Province stations, packed for home and hospitality. In the cooler months we come back to a simple cup — fresh beans, a clean brew, and the taste of the hills.</p><p>Ask us for the current roast profiles and bag sizes. Orders are by request to info@gmac.coffee.</p>', 0, '2024-10-03 09:00:00', '2026-09-23 19:42:22', '2026-09-24 07:33:47', NULL),
(6, 'Coffee Roasting', 'coffee-roasting', 'Roasting coffee is where the magic truly happens! It’s the process of transforming green coffee beans into the rich, aromatic coffee we all love. By carefully controlling time and temperature, the beans develop a unique…', '<p>Roasting coffee is where the magic truly happens! It’s the process of transforming green coffee beans into the rich, aromatic coffee we all love. By carefully controlling time and temperature, the beans develop a unique balance of flavors, unlocking their full potential.</p>\n<p><strong>How It Works:</strong> During roasting, the beans go through various stages, from light to dark roast, each bringing out different flavor profiles. A light roast offers more acidity and fruity notes, while a dark roast brings out bold, smoky flavors. It’s all about finding that perfect balance!</p>\n<p><strong>Why Fresh Roasting Matters:</strong></p><ul class=\"wp-block-list\">\n<li><strong>Fresher Coffee</strong>: Freshly roasted coffee delivers a more vibrant and aromatic experience compared to pre-packaged, stale beans.</li>\n<li><strong>Better Flavor Control</strong>: Roasting in small batches allows for greater precision, ensuring that each bean develops its ideal flavor profile.</li>\n<li><strong>Customization</strong>: Whether you prefer a light, medium, or dark roast, roasting gives you the ability to craft coffee just the way you like it.</li></ul>\n<p>We’re excited to share that we’ll soon be starting our coffee roasting journey after acquiring our own roasting machine! Fresh, flavorful coffee is just around the corner, and we can’t wait to share the results.</p>\n<p>CoffeeRoasting #FreshRoast #CoffeeLovers #RoastingProcess #CraftCoffee #ArtOfRoasting</p>', 1, '2024-09-06 09:02:48', '2026-09-23 19:42:22', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2024/09/pexels-jdgromov-4765838.jpg'),
(7, 'We’re in the top 40 of Best of Rwanda Specialty Coffee 2024', 'top-40-best-of-rwanda-specialty-coffee-2024', 'GMAC coffee reached the top 40 in the Best of Rwanda Specialty Coffee 2024 competition and auction.', '<p>GMAC coffee placed in the top 40 of Best of Rwanda Specialty Coffee 2024 — the national competition and auction that shows the country’s best lots. The result belongs to the farmers and the station teams who kept cherry selection and processing tight through a difficult climate year.</p><p>Best of Rwanda is the stage we work toward each season: clean washed cups, honest lots, and a place among the country’s specialty coffees.</p>', 0, '2024-07-03 09:00:00', '2026-09-23 19:42:22', '2026-09-24 07:33:47', NULL),
(8, 'Harvest season is here', 'harvest-season-is-here-2024', 'Ripe cherries are arriving at the stations. Farmers pick by hand; we float, pulp, and dry lot by lot.', '<p>Harvest has opened on the hills. Farmers pick ripe red cherries by hand and deliver them the same day. At the station we float, pulp, ferment, wash, grade, and dry — then cup each lot before it moves on.</p><p>This is the stretch of the year that decides the cup. Write to us if you want samples from the current intake.</p>', 0, '2024-06-04 09:00:00', '2026-09-23 19:42:22', '2026-09-24 07:33:47', NULL),
(9, 'Coffee Cupping', 'coffee-cupping', 'Hey coffee enthusiasts! Are you ready to dive into the fascinating world of coffee cupping? Whether you\'re a newbie or a seasoned coffee aficionado, coffee cupping is a fantastic way to explore the diverse flavors and ar…', '<p>Hey coffee enthusiasts! Are you ready to dive into the fascinating world of coffee cupping? Whether you\'re a newbie or a seasoned coffee aficionado, coffee cupping is a fantastic way to explore the diverse flavors and aromas of different coffee beans. In this blog post, we\'ll break down the basics of coffee cupping in easy-to-understand language, so let\'s get started!</p><h3 class=\"wp-block-heading\">What is Coffee Cupping?</h3>\n<p>Coffee cupping is like a wine tasting but for coffee. It\'s a sensory evaluation process used by coffee professionals and enthusiasts to assess the aroma, flavor, acidity, body, and aftertaste of coffee beans. It helps in understanding the unique characteristics of different coffee beans and origins.</p><h3 class=\"wp-block-heading\">How to Conduct a Coffee Cupping Session:</h3><ol>\n<li><strong>Gather Your Supplies</strong>: You\'ll need freshly roasted coffee beans, a grinder, hot water (just off boiling), cups, spoons, and a cupping form (optional).</li>\n<li><strong>Grind the Coffee</strong>: Grind the coffee beans to a coarse consistency.</li>\n<li><strong>Smell the Aromas</strong>: Take a moment to inhale the fragrance of the freshly ground coffee. Note any distinctive aromas.</li>\n<li><strong>Add Hot Water</strong>: Pour hot water over the coffee grounds. Let it steep for a few minutes.</li>\n<li><strong>Break the Crust</strong>: After steeping, break the crust by gently stirring the coffee with a spoon. This releases the aroma.</li>\n<li><strong>Taste the Coffee</strong>: Use a spoon to slurp the coffee, allowing it to coat your entire palate. Note the flavor, acidity, body, and aftertaste.</li>\n<li><strong>Record Your Observations</strong>: Document your impressions on the cupping form or a notebook. Pay attention to the nuances of each coffee.</li></ol><h3 class=\"wp-block-heading\">Why Coffee Cupping?</h3><ul>\n<li><strong>Develop Your Palate</strong>: Coffee cupping helps refine your sense of taste and smell, allowing you to appreciate coffee on a deeper level.</li>\n<li><strong>Discover New Flavors</strong>: Explore the diverse world of coffee flavors from different regions and processing methods.</li>\n<li><strong>Quality Assessment</strong>: Coffee cupping is a standard method used by professionals to evaluate the quality of coffee beans.</li></ul><h3 class=\"wp-block-heading\">Conclusion:</h3>\n<p>Coffee cupping is a fun and educational way to explore the complex world of coffee. Whether you\'re a coffee enthusiast or someone looking to expand your palate, coffee cupping offers a unique sensory experience that can deepen your appreciation for this beloved beverage.</p>\n<p>So, grab your favorite coffee beans and embark on a journey of flavors and aromas through coffee cupping!</p><h3 class=\"wp-block-heading\">Hashtags:</h3>\n<p>#CoffeeCupping #CoffeeTasting #CoffeeLovers #SensoryExperience #CoffeeCulture #ExploringFlavors #CoffeeJourney</p>', 1, '2024-02-09 07:00:34', '2026-09-23 19:42:22', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2024/02/IMG_0256.jpg'),
(10, 'Why GMAC is a coffee destination', 'why-gmac-is-your-coffee-destination', 'GMAC is a farmer, processor, and exporter — two stations, Arabica Bourbon, and a direct line to the people who process the coffee.', '<p>GMAC is not a supermarket brand. We farm, process, and export Arabica Bourbon from two washing stations in Rwanda’s Eastern Province. Buyers talk to the same people who receive cherry and cup the lots.</p><p>If you want samples, a station visit, or retail Ntwali bags, write to info@gmac.coffee.</p>', 0, '2024-01-16 09:00:00', '2026-09-23 19:42:22', '2026-09-24 07:33:47', NULL),
(11, 'GMAC coffee seedlings for the next season', 'coffee-seedlings-preparation-next-season', 'The next harvest starts in the nursery. We select seed, raise seedlings, and send strong plants to the hills.', '<p>The next cup starts as a seedling. We select seed from healthy Arabica plants, raise it in the nursery, and only send plants that are strong enough for the hills.</p><p>That work sits behind every later harvest: better trees, better cherry, and a more stable supply from partner farmers.</p>', 0, '2023-12-15 09:00:00', '2026-09-23 19:42:22', '2026-09-24 07:33:47', NULL),
(12, 'GMAC supports Gasange farmers with Ejo Heza pension planning', 'gasange-ejo-heza-pension-support', 'GMAC visited the Gasange Coffee Farmers Cooperative to support Ejo Heza pension planning and insurance.', '<p>GMAC visited the Gasange Coffee Farmers Cooperative with sector leaders to talk through Ejo Heza — Rwanda’s long-term savings scheme — and insurance. The visit was about the people who grow the coffee, not only the cherry they deliver.</p><p>Gasange is one of our two stations. Standing with that cooperative is part of how we keep the partnership real.</p>', 0, '2023-10-31 09:00:00', '2026-09-23 19:42:22', '2026-09-24 07:33:47', NULL),
(13, 'Mutuelle de Santé for women coffee farmers', 'mutuelle-de-sante-women-coffee-farmers', 'GMAC paid community health-insurance fees for women farmers as part of our Mutuelle de Santé support.', '<p>GMAC supported women coffee farmers through Mutuelle de Santé — community health insurance — covering fees so households stay in the scheme. Coffee work is seasonal and uncertain; insurance is one of the few protections that lasts after harvest.</p><p>Women carry much of the work on the beds and in the fields. This is a direct way to stand with them.</p>', 0, '2023-10-10 09:00:00', '2026-09-23 19:42:22', '2026-09-24 07:33:47', NULL),
(14, 'Why Wear Boots While Washing Coffee?', 'why-wear-boots-while-washing-coffee', 'Standing in Water: Coffee beans are washed in large water tanks or channels during the washing process. Workers need to stand in this water as they agitate and stir the beans to remove the mucilage effectively. Boots pro…', '<p><strong>Standing in Water: </strong>Coffee beans are washed in large water tanks or channels during the washing process. Workers need to stand in this water as they agitate and stir the beans to remove the mucilage effectively. Boots protect their feet from prolonged exposure to water.</p>\n<p><strong>Hygiene and Safety: </strong>Coffee washing stations can get quite messy. With beans, mucilage, and water all around, boots provide a barrier that helps maintain hygiene and prevents slipping accidents.</p>\n<p><strong>Temperature Control: </strong>Depending on the region, coffee washing can take place in various environmental conditions. Boots offer insulation, keeping the feet of coffee workers comfortable, especially in colder or wetter climates.</p>\n<p><strong>Long Hours: </strong>Coffee washing can be a labor-intensive process, often requiring workers to stand for extended periods. Comfortable, waterproof boots are essential to ensure the well-being of these hardworking individuals.</p>\n<p>As conclusion coffee washing is a crucial step in the coffee production process that ensures the beans you brew at home are of the highest quality. The requirement to wear boots during this process might seem like a minor detail, but it plays a vital role in the well-being and safety of the workers involved.</p>\n<p>The next time you enjoy a cup of coffee, take a moment to appreciate the effort that goes into each bean\'s journey, from the coffee cherry to your cup, and the importance of those trusty boots in making it all happen.❤️👏☕</p>', 1, '2023-09-14 06:42:35', '2026-09-23 19:42:22', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/09/1.jpg'),
(15, 'The art of coffee sorting', 'the-art-of-coffee-sorting', 'After the wash, hands still decide what stays in the lot. Sorting is slow, and it shows in the cup.', '<p>After washing, parchment is sorted by hand. Defects, broken beans, and off-colour seeds leave the lot before drying finishes. It is slow work, often done by women on the beds, and it is one of the reasons a cup stays clean.</p><p>We do not skip it. A pretty process on paper still fails if the table is careless.</p>', 0, '2023-08-28 09:00:00', '2026-09-23 19:42:22', '2026-09-24 07:33:47', NULL),
(16, 'A successful harvest season at GMAC', 'successful-harvest-season-2023', 'The 2023 harvest closed with strong volumes and cups we were proud to send out.', '<p>The 2023 harvest closed with the work we ask of every season: ripe cherry, honest processing, and lots we could stand behind on the cupping table. Farmers and station teams carried that stretch together.</p><p>When harvest ends we keep cupping, milling, and talking to buyers. The next season starts as soon as the last parchment is bagged.</p>', 0, '2023-07-11 09:00:00', '2026-09-23 19:42:22', '2026-09-24 07:33:47', NULL),
(17, 'GMAC at the China Coffee Expo', 'china-coffee-expo-2023', 'GMAC attended the China Coffee Expo to meet buyers, share lots, and learn with the wider trade.', '<p>GMAC attended the China Coffee Expo to meet buyers and sit in industry sessions. It was a chance to put Rwandan Arabica in a room that is still building its specialty trade.</p><p>We came home with contacts and a clearer sense of what that market asks for: consistent lots, clean communication, and samples that match the offer.</p>', 0, '2023-07-10 09:00:00', '2026-09-23 19:42:22', '2026-09-24 07:33:47', NULL),
(18, 'Rabobank funds our coffee hulling project', 'rabobank-coffee-hulling-project', 'Rabobank Netherlands funded a hulling project so more value from parchment stays in the community.', '<p>A hulling project supported by Rabobank Netherlands is helping GMAC keep more of the dry mill close to origin. Hulling parchment locally means jobs and a higher share of value before export.</p><p>The bank’s Africa programme team visited as the work moved forward. The goal is a plant that serves farmers, not only a single company line.</p>', 0, '2023-04-28 09:00:00', '2026-09-23 19:42:22', '2026-09-24 07:33:47', NULL),
(19, 'Natural Coffee Processing', 'natural-coffee-processing', 'Natural coffee processing is a method of processing coffee beans that involves drying the beans inside the fruit, rather than removing the fruit first. This method of processing is often used in countries with dry climat…', '<p>Natural coffee processing is a method of processing coffee beans that involves drying the beans inside the fruit, rather than removing the fruit first. This method of processing is often used in countries with dry climates, such as Brazil,but here at GMAC we also prepare it, where the fruit can be left to dry in the sun. Here\'s a breakdown of the natural coffee processing phase from farm until it\'s dried:</p><ol>\n<li>Harvesting: Coffee is typically harvested when the fruit is ripe, which can take up to nine months after flowering. The cherries are picked by hand or by machine, depending on the farm\'s resources.</li>\n<li>Sorting: After harvesting, the coffee cherries are sorted to remove any overripe, underripe, or damaged fruit.</li></ol><figure class=\"wp-block-image size-large is-style-default\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/04/P9A0055-1024x683.jpg\" alt=\"Natural Coffee Sorting Process-GMAC(Green Mountain Arabica Coffee)\" class=\"wp-image-16190\"/></figure>\n<p>3.Drying: In natural coffee processing, the cherries are dried with the fruit still intact. This can be done in a few different ways:</p><figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><figure class=\"wp-block-image size-full\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/04/Gmac_2.jpg\" alt=\"Natural Coffee Drying Process-GMAC(Green Mountain Arabica Coffee)\" class=\"wp-image-16186\" title=\"Natural Coffee Drying Process-GMAC(Green Mountain Arabica Coffee)\"/></figure></figure>\n<p>4.Fermentation: During the drying process, the cherries ferment, which can give the coffee a unique flavor. The length of fermentation can vary depending on the farm\'s preferences, but it typically lasts between one and three days.</p>\n<p>5.Hulling: After the coffee beans are dry, the fruit is removed through a process called hulling. This can be done by machine or by hand.</p>\n<p>6.Sorting and grading: Once the fruit is removed, the coffee beans are sorted by size and quality. The beans are then graded based on their appearance, flavor, and aroma.</p>\n<p>7.Roasting: The final step in the natural coffee processing phase is roasting. Roasting brings out the flavor of the coffee beans and determines the final taste of the coffee.</p>\n<p>In conclusion, natural coffee processing is a unique method of processing coffee beans that involves drying the cherries with the fruit still intact. This process can take several weeks and involves several steps, including sorting, drying, fermentation, hulling, and grading. The end result is a coffee bean with a distinct flavor and aroma that is highly prized by coffee connoisseurs around the world.</p>', 1, '2023-04-21 06:05:14', '2026-09-23 19:42:22', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/03/Gmac_3.jpg'),
(20, 'Coffee harvesting season has begun', 'harvest-season-has-begun-2023', 'The 2023 harvest opened at GMAC. Farmers are picking, and the stations are receiving cherry every morning.', '<p>Harvest opened again in 2023. The smell of ripe cherry on the road to the station is the start of the working year. Farmers pick, we receive, and the first tanks fill.</p><p>From here the sequence is the one we never skip: seedlings already in the ground, farm work done, harvest, process, cup.</p>', 0, '2023-03-31 09:00:00', '2026-09-23 19:42:22', '2026-09-24 07:33:47', NULL),
(21, 'Insights from AgriTech 2023 in Qatar', 'agritech-exhibition-qatar-2023', 'GMAC joined coffee farmers at AgriTech in Qatar to talk climate, practice, and new tools.', '<p>GMAC took part in the AgriTech coffee farmers meeting in Qatar. Growers compared notes on climate, pests, and the tools that actually help a small station — not only a slide deck.</p><p>Climate stress was the shared problem. The useful answers were still the old ones done well: healthy trees, shade, and a station that does not waste a cherry.</p>', 0, '2023-03-28 09:00:00', '2026-09-23 19:42:22', '2026-09-24 07:33:47', NULL),
(22, 'Coffee Processing-Wet Processing', 'coffee-processing-wet-processing', 'Coffee is generally wet processed throughout the country. This is largely thanks to modern efforts to invest time, effort, and resources into developing communal washing stations for the countless micro-crops of coffee c…', '<p>Coffee is generally wet processed throughout the country. This is largely thanks to modern efforts to invest time, effort, and resources into developing communal washing stations for the countless micro-crops of coffee cherries that require processing each year.</p>\n<p><em>In this video you can check our washing station (gmac) and how it is done:</em></p><figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"> https://www.youtube.com/watch?v=56FvySZwBKk </figure>\n<p>The numerous small farms involved in the business cannot create large, individual washing stations like the great coffee estates throughout the world do. This is because most farmers only grow coffee as a part-time side gig, generally using the rest of their farms to grow food.</p>\n<p>Therefore, the investment into these washing stations has paid off, as access to decent washing facilities has helped raise the quantity and quality of Rwandan coffee to a whole new level.</p>', 1, '2022-12-20 10:46:02', '2026-09-23 19:42:22', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2022/12/IMG_5572Ikawa.jpg'),
(23, 'Rwanda coffee growing: what you need to know', 'rwanda-coffee-growing', 'Rwanda’s coffee is Arabica from steep hills. The country’s trade was rebuilt around washing stations and cup quality.', '<p>Rwanda grows Arabica on steep hills. After the 1990s the industry was rebuilt around washing stations, tighter processing, and a cup that could sell as specialty — not only as volume.</p><p>GMAC sits in that story: two stations in the Eastern Province, Bourbon on sandy soils, and a table that still cups lot by lot. That is the Rwanda we export.</p>', 0, '2022-12-19 09:00:00', '2026-09-23 19:42:22', '2026-09-24 07:33:47', NULL),
(24, 'GMAC at the European Coffee Exhibition: Showcasing Ntwali Coffee', 'gmac-at-the-european-coffee-exhibition-showcasing-ntwali-coffee', 'At GMAC, our journey has always been rooted in excellence, authenticity, and a deep passion for coffee. This year marked a significant milestone for us as we proudly participated in a prestigious coffee exhibition in Eur…', '<p>At GMAC, our journey has always been rooted in excellence, authenticity, and a deep passion for coffee. This year marked a significant milestone for us as we proudly participated in a prestigious coffee exhibition in Europe bringing the rich taste of Rwanda to an international audience.</p>\n<p><strong>A Global Stage for Rwandan Coffee</strong></p>\n<p>The exhibition brought together coffee enthusiasts, roasters, distributors, and innovators from across the world. It was more than just an event it was a celebration of culture, craftsmanship, and connection through coffee.</p>\n<p>For GMAC, this was an incredible opportunity to represent Rwanda’s growing coffee industry and share our story with a global community.</p><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2026/03/645726018_18299702773263505_9070978751929692412_n-769x1024.jpg\" alt=\"\" class=\"wp-image-16363\"/></figure>\n<p><strong>Introducing Ntwali Coffee</strong></p>\n<p>At the heart of our showcase was our signature product: Ntwali Coffee.</p>\n<p>Carefully sourced from Rwanda’s fertile highlands and crafted with precision, Ntwali Coffee reflects:</p>\n<p>Rich volcanic soil origins<br>Handpicked, high-quality beans<br>Expert roasting techniques<br>A smooth, aromatic flavor profile</p>\n<p>Our packaged coffee stood out not only for its taste but also for its elegant branding and commitment to quality.</p><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2026/03/645759844_18299702791263505_2949542972133172724_n-768x1024.jpg\" alt=\"\" class=\"wp-image-16362\"/></figure>\n<p><strong>Engaging with Coffee Lovers Worldwide</strong></p>\n<p>Visitors from different countries stopped by our booth to experience Ntwali Coffee firsthand. From first sip to final note, the response was overwhelmingly positive.</p>\n<p><strong>We had meaningful conversations with:</strong></p>\n<p>Coffee importers and distributors<br>Café owners and baristas<br>Coffee lovers curious about African beans</p>\n<p>Each interaction reinforced the global appreciation for authentic, high-quality coffee and the unique place Rwanda holds in that story.</p>\n<p><strong>Packaging that Tells a Story</strong></p>\n<p>Our packaging was designed to reflect both modern quality and cultural identity. It tells the story of where our coffee comes from, the people behind it, and the care put into every bean.</p>\n<p>Many visitors were impressed not jjust by the taste, but by the complete experience from visual appeal to aroma.</p><h3 class=\"wp-block-heading\">Looking Ahead</h3>\n<p>Participating in the European coffee exhibition was more than just a showcase it was a step forward in our mission to expand GMAC’s presence globally.</p>\n<p>We return inspired, motivated, and more committed than ever to delivering exceptional coffee to the world.</p>', 1, '2026-03-24 14:29:31', '2026-09-24 07:33:01', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2026/03/643583815_18299702800263505_3564552887130536193_n.jpg'),
(25, 'Warm Up This Cold Season with NTWALI Coffee!', 'warm-up-this-cold-season-with-ntwali-coffee', 'As the cold weather settles in, there’s no better way to keep warm than with a steaming cup of freshly brewed coffee. At NTWALI Coffee, we believe that the chill in the air is a perfect excuse to indulge in the rich, aro…', '<p>As the cold weather settles in, there’s no better way to keep warm than with a steaming cup of freshly brewed coffee. At NTWALI Coffee, we believe that the chill in the air is a perfect excuse to indulge in the rich, aromatic flavors of our sustainably sourced beans. Our coffee is more than just a drink; it’s an experience that brings comfort and warmth to your day.</p><h3 class=\"wp-block-heading\">Why Coffee is the Perfect Cold-Weather Companion</h3>\n<p>In the colder months, our bodies crave warmth, and coffee is one of the best ways to get it. Whether you prefer it black, with a splash of milk, or infused with seasonal flavors like cinnamon or vanilla, coffee has a way of lifting your spirits and energizing you when the temperature drops. The natural caffeine in coffee is not only a great way to stay alert, but it also stimulates your metabolism, giving you that cozy inner warmth.</p><h3 class=\"wp-block-heading\">NTWALI Coffee: The Taste of Comfort</h3>\n<p>Our NTWALI Coffee beans are handpicked from the highlands of Rwanda by members of the ABADACOGORA Cooperative, skilled women and youth who practice sustainable farming. This ensures that every cup you brew is filled with care, passion, and the authentic taste of Rwanda’s finest coffee. With each purchase, we also give back to the farmers by sharing 10% of our profits with them, helping to improve their lives and reward their hard work.</p><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2024/10/dc7ad4b3-1742-4ed3-ae2f-c65516e538d1-847x1024.jpeg\" alt=\"\" class=\"wp-image-16351\"/></figure><h3 class=\"wp-block-heading\">Drink Good, Feel Good</h3>\n<p>There’s something magical about sitting by the window, watching the rain or cold winds, with a warm mug in hand. Why not make your experience even better by enjoying a coffee that not only tastes great but also supports communities? NTWALI Coffee gives you that satisfying feeling of doing good while drinking good.</p><h3 class=\"wp-block-heading\">How to Enjoy NTWALI Coffee this Season</h3><ul class=\"wp-block-list\">\n<li><strong>Morning Brew</strong>: Start your day with a hot cup of NTWALI Coffee to keep the winter blues at bay.</li>\n<li><strong>Afternoon Warm-up</strong>: Take a break from the cold with a mid-day coffee, pairing it with your favorite snack.</li>\n<li><strong>Evening Wind-down</strong>: Unwind in the evening with a warm coffee, perhaps accompanied by a good book or your favorite podcast.</li></ul>\n<p>This cold season, don’t let the chilly weather keep you down. Stay warm, stay cozy, and enjoy the full-bodied flavor of NTWALI Coffee.</p>\n<p>So go ahead, grab your NTWALI Coffee today, and let the warmth flow through every sip!</p>\n<p><strong>Stay warm. Stay caffeinated.</strong></p>', 1, '2024-10-03 07:56:10', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2024/10/8891f09c-0655-4edb-8c11-a20393e27fc8.jpeg'),
(26, 'We\'re In Top 40 in the Best of Rwanda Specialty Coffee 2024!', 'were-in-top-40-in-the-best-of-rwanda-specialty-coffee-2024', 'We are excited to announce that our coffee has made it to the top 40 in the \"Best of Rwanda Specialty Coffee 2024\" competition! This recognition reflects the dedication and hard work we put into every bean we produce.The…', '<p>We are excited to announce that our coffee has made it to the top 40 in the \"Best of Rwanda Specialty Coffee 2024\" competition! This recognition reflects the dedication and hard work we put into every bean we produce.</p><h4 class=\"wp-block-heading\">The Journey So Far</h4>\n<p>Best Of Rwanda is an annual specialty coffee competition and auction showcasing the country\'s finest coffee. Despite the challenges posed by climate change and market volatility, our smallholder farmers have consistently produced exceptional coffee using good agricultural practices. Our inclusion in the top 40 is a significant achievement, reflecting our commitment to quality and excellence.</p><h4 class=\"wp-block-heading\">What’s Next?</h4>\n<p>We are now eagerly awaiting the final round, where the top 10 best coffees will be selected. This final stage will be an intense competition, bringing together the finest coffee producers from Rwanda.</p><h4 class=\"wp-block-heading\">Our Commitment to Excellence</h4>\n<p>As we move forward, our focus remains on maintaining the highest standards in our coffee production. Every cup of our coffee is a blend of meticulous care, innovative practices, and a deep respect for the art of coffee making.</p><h4 class=\"wp-block-heading\">Thank You for Your Support</h4>\n<p>We extend our gratitude to our supporters, partners, and the coffee-loving community. Your encouragement has been a driving force behind our success. We are proud to represent Rwanda on this prestigious platform and are committed to bringing the best coffee experience to our consumers.</p>\n<p>Stay tuned for more updates as we await the final results. Join us in celebrating and exploring the best coffee Rwanda has to offer!</p>', 1, '2024-07-03 07:33:25', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2024/07/Snapinsta.app_449534448_470322455581487_2096743218479007885_n_1080.jpg'),
(27, 'Discover the Rich Flavors of GMAC Coffee: Harvest Season is Here!', 'discover-the-rich-flavors-of-gmac-coffee-harvest-season-is-here', 'As the sun rises over the lush hills of our coffee plantations, a symphony of nature begins. The air is filled with the rich aroma of freshly picked coffee cherries, signaling the start of GMAC Coffee\'s most anticipated…', '<p>As the sun rises over the lush hills of our coffee plantations, a symphony of nature begins. The air is filled with the rich aroma of freshly picked coffee cherries, signaling the start of GMAC Coffee\'s most anticipated time of the year – the harvesting season. This is when the true magic happens, and we\'re excited to share it with you.</p><h4 class=\"wp-block-heading\">Handpicked with Love and Care</h4>\n<p>At GMAC Coffee, we believe in the art of coffee. Our dedicated farmers handpick each coffee cherry at the peak of ripeness, ensuring only the best beans make it to your cup. This meticulous process not only guarantees superior quality but also supports our commitment to sustainable and ethical farming practices.</p><h4 class=\"wp-block-heading\">A Journey from Bean to Brew</h4>\n<p>Every cup of GMAC Coffee is a testament to our passion for perfection. From the moment the cherries are harvested, they undergo a series of steps – from drying and milling to roasting and packaging – all carefully managed to preserve their unique flavors. Our expert roasters bring out the distinct characteristics of each batch, creating a harmonious blend that is both rich and complex.</p><h4 class=\"wp-block-heading\">Why Harvest Season Matters</h4>\n<p>The harvesting season is a celebration of hard work and dedication. It\'s the time when the fruits of our labor come to life, offering you a taste that is fresh, vibrant, and full of character. This year\'s harvest promises exceptional quality, thanks to the ideal weather conditions and the tireless efforts of our team.</p><h4 class=\"wp-block-heading\">Join Us in the Celebration</h4>\n<p>We invite you to be a part of this exciting journey. Experience the freshest brews by trying our latest harvest collection, available now for a limited time. Whether you prefer a bold espresso or a smooth, creamy latte, GMAC Coffee has something to delight every palate.</p><h4 class=\"wp-block-heading\">Special Offers Just for You</h4>\n<p>To celebrate this special season, we\'re offering exclusive discounts and bundles on our newest harvest. Visit our website or your nearest GMAC Coffee retailer to take advantage of these limited-time offers. Share the joy of freshly harvested coffee with friends and family, or simply treat yourself to a moment of indulgence.</p><h4 class=\"wp-block-heading\">Taste the Difference</h4>\n<p>There\'s something truly special about coffee that is harvested with care and passion. We can\'t wait for you to taste the difference. Thank you for being a part of the GMAC Coffee family. Here\'s to a bountiful harvest and many delicious cups of coffee ahead!</p><hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<p><strong>Follow us on social media</strong> for behind-the-scenes glimpses of our harvest season, updates on new products, and special promotions. Cheers to a wonderful season filled with the finest coffee!</p>\n<p><strong>GMAC Coffee – From Our Fields to Your Cup.</strong></p>', 1, '2024-06-04 06:55:24', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2024/06/f740a92f-ab92-4cd1-b3d2-97bfb9c39b70.jpg'),
(28, 'Why GMAC is Your Coffee Destination for 2024?', 'why-gmac-is-your-coffee-destination-for-2024', 'Raise your mugs, coffee lovers! 2024 is here, and what better way to kick off the year than with a fresh, invigorating cup of quality brew? Look no further than GMAC, your one-stop shop for all things coffee! Whether you…', '<p>Raise your mugs, coffee lovers! 2024 is here, and what better way to kick off the year than with a fresh, invigorating cup of quality brew? Look no further than GMAC, your one-stop shop for all things coffee!</p>\n<p>Whether you\'re a seasoned connoisseur, a casual cappuccino cruiser, or just starting your espresso odyssey, GMAC has something for every palate and every preference. We\'re not just talking your average supermarket beans here. We\'re talking hand-picked, ethically sourced, meticulously roasted perfection. We boast:</p>\n<p>A world of flavors: From bright Ethiopian Yirgacheffe to rich Sumatran Mandheling, our diverse selection takes you on a global coffee adventure, right from your own cup.<br>Freshness to the brim: We roast our beans in small batches, ensuring peak flavor and aroma. Forget stale supermarket coffee! Every sip is a burst of joy.<br>Expert guidance: Our passionate team knows their beans. Whether you need help navigating brewing methods, deciphering roast levels, or discovering your perfect pairing, we\'re here to guide you.<br>More than just beans: We offer everything you need to craft the perfect cup, from French presses and grinders to stylish mugs and chic coffee makers.<br>Supporting good vibes: We\'re committed to ethical sourcing and sustainable practices, so you can sip with a clear conscience knowing your coffee choice makes a difference.<br>So, this year, ditch the boring brews and join the GMAC coffee revolution. We\'re not just selling coffee; we\'re selling experiences, connections, and moments of pure, delicious bliss. Here\'s to new beginnings, exciting possibilities, and of course, countless amazing cups of coffee.</p>\n<p>Make GMAC your coffee destination for 2024!</p>\n<p>Explore our online store or visit us in person for a sensory coffee exploration.<br>Follow us on social media for brewing tips, coffee trivia, and exclusive offers.<br>Share your coffee journey with us using <a href=\"https://www.instagram.com/explore/tags/gmaccoffeelife/\">#GMACcoffeelife</a>.<br>Let\'s make this year one sip at a time, starting with a perfect cup from GMAC!</p>\n<p>Cheers to a caffeinated 2024!</p>', 1, '2024-01-16 20:40:11', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2024/01/419512392_1550454235714271_7243546436328580574_n.jpg'),
(29, 'GMAC Coffee Seedlings Preparation For The Next Season', 'from-seed-to-sip-the-journey-of-gmac-coffee', 'Welcome to the world of Green Mountain Arabica Coffee (GMAC), where every sip starts with a tiny seed and a whole lot of love! Today, we\'re taking you behind the scenes to explore the incredible journey of our coffee see…', '<p>Welcome to the world of Green Mountain Arabica Coffee (GMAC), where every sip starts with a tiny seed and a whole lot of love! Today, we\'re taking you behind the scenes to explore the incredible journey of our coffee seedlings, from the moment they\'re chosen to the day they reach your cup.</p>\n<p><strong>Step 1: Selecting the Perfect Bean</strong></p>\n<p>It all begins with the bean. We hand-select only the finest Arabica coffee seeds, ensuring they meet our rigorous standards for quality and potential. These aren\'t your average supermarket beans – we\'re talking about the crème de la crème,bursting with flavor and ready to thrive in diverse climates.</p>\n<p><strong>Step 2: Witnessing the Magic of Germination</strong></p>\n<p>Next comes the moment of magic: germination. We carefully plant our chosen seeds in specially formulated soil,providing them with the perfect balance of warmth, moisture, and sunshine. As if by enchantment, tiny green shoots begin to peek through, marking the start of their incredible transformation.</p>\n<p><strong>Step 3: Nurturing Champions in the Nursery</strong></p>\n<p>Once our seedlings sprout, they graduate to our state-of-the-art nurseries. Here, our skilled technicians become their guardians, monitoring their growth and providing them with the precise care they need. We\'re talking sunlight therapy,nutrient-rich feedings, and the watchful eyes of experienced coffee whisperers.</p>\n<p><strong>Step 4: Making Room to Grow</strong></p>\n<p>As the seedlings mature, they start yearning for more space. That\'s when we gently transplant them into bigger containers or directly into the fields. This gives them the room they need to stretch their roots, soak up the sun, and dream of becoming the coffee heroes they were destined to be.</p>\n<p><strong>Step 5: Joining Hands with Passionate Farmers</strong></p>\n<p>At GMAC, we believe in the power of collaboration. That\'s why we partner with passionate farmers who share our dedication to quality and sustainability. We provide them with our nurtured seedlings, along with training and support, to help them cultivate exceptional coffee beans. Together, we\'re building a community that values the journey from seed to sip.</p>\n<p><strong>The Grand Finale: Your Cup of GMAC Magic</strong></p>\n<p>And finally, the moment we\'ve all been waiting for: your first sip of GMAC coffee. Every drop is a testament to the care,passion, and dedication that went into nurturing those tiny seeds. It\'s the culmination of a journey that began with a promise of quality and blossomed into a cup of pure, unadulterated coffee bliss.</p>\n<p>So, the next time you savor a cup of GMAC, remember the incredible journey it took to get there. From the meticulous seed selection to the watchful care in our nurseries, from the supportive partnership with our farmers to the dedication of every single person involved, every sip is a celebration of the art and science of coffee cultivation.</p>\n<p><strong>Join us on this journey!</strong> Follow us on social media, visit our farms, and experience the magic of GMAC coffee firsthand.Because every cup is more than just a drink; it\'s a story waiting to be savored.</p>\n<p>We hope you enjoyed this glimpse into the world of GMAC coffee! Let us know in the comments below what you\'d like to learn more about, and keep an eye out for our future blog posts, where we\'ll be diving deeper into the fascinating world of coffee cultivation.</p>', 1, '2023-12-15 06:44:43', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/12/RDU1631.jpg'),
(30, 'GMAC Supports Gasange Coffee Farmers Cooperative by providing  Ejo Heza pension planning support', 'gmac-supports-gasange-coffee-farmers-cooperative-by-providing-ejo-heza-pension-planning-support', 'In a heartwarming initiative, GMAC recently visited the Gasange Cooperative of Coffee Farmers. This visit aimed to not only show support and solidarity but also to encourage the farmers to follow essential government saf…', '<p>In a heartwarming initiative, GMAC recently visited the Gasange Cooperative of Coffee Farmers. This visit aimed to not only show support and solidarity but also to encourage the farmers to follow essential government safety guidelines, particularly focusing on \"Ejo Heza\" (pension planning) and insurance fees. GMAC, along with sector executives and other community leaders, joined hands with the cooperative members, demonstrating the company\'s commitment to the well-being of the local coffee farming community.</p><figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/10/IMG_0585-768x1024.jpg\" alt=\"\" class=\"wp-image-16271\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/10/IMG_0573-768x1024.jpg\" alt=\"\" class=\"wp-image-16270\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/10/IMG_0575-768x1024.jpg\" alt=\"\" class=\"wp-image-16269\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/10/IMG_0557-768x1024.jpg\" alt=\"\" class=\"wp-image-16267\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/10/IMG_0556-768x1024.jpg\" alt=\"\" class=\"wp-image-16268\"/></figure></figure>\n<p><strong>GMAC\'s Commitment to the Community</strong></p>\n<p>At GMAC, we firmly believe in giving back to the communities we serve. Our recent visit to the Gasange Cooperative is a testament to our commitment to the people who work tirelessly to produce the high-quality coffee we all love. We understand that their well-being is intrinsically tied to the success of our business, which is why we decided to offer support and guidance to the hardworking coffee farmers.</p>\n<p><strong>Ejo Heza: A Brighter Tomorrow</strong></p>\n<p>\"Ejo Heza\" translates to \"Brighter Tomorrow\" in Kinyarwanda, and that is precisely what we want to help the Gasange coffee farmers achieve. Retirement planning is essential for the long-term financial security and well-being of every individual. During our visit, we educated the cooperative members about the importance of planning for their retirement. Together with sector executives, we explained the benefits of Ejo Heza and how it can pave the way for a more secure future.</p>\n<p><strong>Assisting with Ejo Heza Contributions</strong></p>\n<p>We didn\'t stop at just providing information. GMAC took a step further by offering financial support to the Gasange farmers to kickstart their Ejo Heza contributions. This financial assistance is meant to alleviate the initial burden of saving for retirement, allowing the farmers to envision a brighter, more secure future with confidence.</p><figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/10/IMG_0610-768x1024.jpg\" alt=\"\" class=\"wp-image-16273\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/10/IMG_0599-768x1024.jpg\" alt=\"\" class=\"wp-image-16272\"/></figure></figure>\n<p><strong>Emphasizing the Importance of Insurance</strong></p>\n<p>In addition to Ejo Heza, we emphasized the significance of insurance fees. Insurance acts as a safety net, protecting farmers and their families in case of unexpected events or emergencies. By educating the cooperative members about the various insurance options available, we hope to foster a sense of financial security and peace of mind among the community.</p>\n<p><strong>Collaboration with Sector Executives and Community Leaders</strong></p>\n<p>Our visit wouldn\'t have been as impactful without the collaboration of sector executives and other community leaders. Together, we demonstrated the importance of unity and support in creating a thriving, safe, and sustainable community.</p>\n<p>GMAC\'s visit to the Gasange Cooperative of Coffee Farmers exemplifies our dedication to the well-being of the local community. We are committed to helping the coffee farmers plan for a \"Brighter Tomorrow\" through Ejo Heza and ensuring their peace of mind with insurance coverage. We look forward to continuing our partnership with Gasange farmers and other communities, fostering a spirit of unity and support for a prosperous future.</p>\n<p>By working together, we can create a better and brighter future for all. GMAC remains devoted to supporting the communities that have contributed to our success, ensuring that their well-being is a priority.</p>', 1, '2023-10-31 18:10:34', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/10/IMG_0564.jpg'),
(31, 'Mastering the Art of Coffee Cupping: Tips for the Perfect Brew', 'mastering-the-art-of-coffee-cupping-tips-for-the-perfect-brew', 'here\'s more to enjoying coffee than a quick morning pick-me-up. For coffee enthusiasts and professionals, coffee cupping is a serious business. It\'s a sensory evaluation process that allows you to savor and assess the un…', '<p><em>here\'s more to enjoying coffee than a quick morning pick-me-up. For coffee enthusiasts and professionals, coffee cupping is a serious business. It\'s a sensory evaluation process that allows you to savor and assess the unique flavors and aromas of coffee beans. Whether you\'re a seasoned pro or a novice, here are some tips to help you elevate your coffee cupping experience.</em></p>\n<p><strong>1. Choose High-Quality Beans:</strong> The foundation of any successful cupping session is the coffee beans themselves. Opt for freshly roasted beans that are sourced from reputable suppliers. Beans from different regions have distinct flavor profiles, so experiment with various origins to expand your palate.</p>\n<p><strong>2. Prepare Your Space:</strong> Cupping is a precise practice that requires a quiet and controlled environment. Ensure that you have good lighting, a clean workspace, and minimal distractions to focus on the coffee\'s nuances.</p>\n<p><strong>3. The Grinder Matters:</strong> Invest in a quality burr grinder. Consistency in grind size is key for a balanced cupping experience. A medium-coarse grind is usually ideal, similar to breadcrumbs.</p>\n<p><strong>4. Use Clean, Filtered Water:</strong> The quality of your water matters as much as the coffee. Use filtered water at a temperature of 195-205°F (90-96°C) for brewing. Inconsistent water can greatly affect your results.</p>\n<p><strong>5. Cupping Bowls and Spoons:</strong> Use standardized cupping bowls with wide rims that allow you to inhale the coffee\'s aroma. Special cupping spoons with shallow bowls are designed to sip and slurp the coffee effectively.</p>\n<p><strong>6. Follow the SCAA Protocol:</strong> The Specialty Coffee Association of America (SCAA) has established a standardized protocol for coffee cupping. This helps ensure consistency in your evaluations and results.</p>\n<p><strong>7. Smell the Dry Grounds:</strong> Start by smelling the dry coffee grounds before adding water. This initial fragrance can give you a hint of what to expect in the cup.</p>\n<p><strong>8. Brew Time:</strong> Allow the coffee to steep for about 4 minutes. This allows the coffee to fully bloom and develop its flavors.</p>\n<p><strong>9. Breaking the Crust:</strong> After the steeping time, gently break the crust that forms on the coffee\'s surface. Take a moment to inhale the aromatic explosion. This step is crucial for assessing the coffee\'s fragrance.</p>\n<p><strong>10. Slurping and Tasting:</strong> When tasting, take a small spoonful and slurp it, allowing the coffee to aerate in your mouth. This helps to evaluate the flavor, acidity, body, and aftertaste. Take notes on your observations.</p>\n<p><strong>11. Scoring the Coffee:</strong> Use a standardized scoring sheet to record your findings. Parameters usually include aroma, flavor, aftertaste, acidity, body, balance, and overall impression.</p>\n<p><strong>12. Compare and Contrast:</strong> To fully appreciate a coffee\'s qualities, compare it with other beans. This helps you understand each coffee\'s unique characteristics.</p>\n<p><strong>13. Remain Silent:</strong> It\'s a common practice to stay silent during the initial evaluation. This prevents any influence from other participants and ensures your judgments are unbiased.</p>\n<p><strong>14. Document Your Findings:</strong> Maintain detailed records of your cupping sessions. This documentation can help you track your preferences and refine your tasting skills over time.</p>\n<p>Coffee cupping is a sensory journey that allows you to explore the world of coffee flavors and aromas. By following these tips and practicing regularly, you\'ll refine your palate and become a coffee connoisseur in no time. Happy cupping!</p>', 1, '2023-10-16 13:31:02', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/10/Gmac_7.jpg'),
(32, 'Nurturing Growth and Resilience: GMAC\'s \"Mituelle de Sante\" Initiative for Women Coffee Farmers', 'nurturing-growth-and-resilience-gmacs-mituelle-de-sante-initiative-for-women-coffee-farmers', 'At GMAC (Green Mountain Arabica Coffee), we believe in the power of local communities and the potential of women farmers. Today, we had the privilege of taking a step towards supporting and motivating these incredible wo…', '<p>At GMAC (Green Mountain Arabica Coffee), we believe in the power of local communities and the potential of women farmers. Today, we had the privilege of taking a step towards supporting and motivating these incredible women by providing them with insurance fees as part of our \"Mituelle de Sante\" initiative.</p>\n<p><strong>The Heart of Our Initiative: Supporting Women Farmers</strong></p>\n<p>Coffee farming is an essential part of many rural communities in our region. However, it often involves numerous challenges, including unpredictable weather patterns, pests, and market fluctuations. For women farmers, these challenges can be even more daunting due to societal inequalities and limited access to resources.</p>\n<p>At GMAC, we recognize the vital role that women play in the coffee farming industry and the impact they have on their communities. Our \"Mituelle de Sante\" initiative aims to address these challenges by providing support and motivation to local women farmers through insurance coverage.</p><figure class=\"wp-block-image size-full\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/10/WhatsApp-Image-2023-10-10-at-12.41.13_2877184a-edited.jpg\" alt=\"\" class=\"wp-image-16255\"/></figure>\n<p><strong>What is \"Mituelle de Sante\"?</strong></p>\n<p>It is a form of community-based health insurance in Rwanda that helps individuals and families access affordable healthcare services. In our context, it goes beyond health to encompass the well-being of the women farmers who are the backbone of our coffee-growing community.</p>\n<p><strong>Our Commitment: A Day at the Coffee Farms</strong></p>\n<p>Today, we embarked on a journey to visit our local women farmers, and it was a day filled with inspiration and gratitude. We handed over insurance fees that will cover various aspects of their lives, including health expenses and more. This initiative is not just about financial support; it\'s about showing these remarkable women that we believe in their potential and are invested in their well-being.</p>\n<p><strong>The Impact of \"Mituelle de Sante\"</strong></p><ol>\n<li><strong>Financial Security:</strong> By providing insurance coverage, we are helping these women secure their financial future and protect themselves and their families in times of need.</li>\n<li><strong>Empowerment:</strong> This initiative empowers women farmers by giving them the confidence to face the uncertainties of coffee farming with a safety net in place.</li>\n<li><strong>Community Building:</strong> \"Mituelle de Sante\" fosters a sense of community and solidarity among the women farmers, as they come together to support one another.</li></ol>\n<p><strong>A Vision for the Future</strong></p>\n<p>Our \"Mituelle de Sante\" initiative is just the beginning of our commitment to empowering women farmers and strengthening our local coffee-growing community. We envision a future where these women are not only resilient coffee producers but also leaders and change-makers in their communities.</p>\n<p>At GMAC, we believe that by investing in the well-being and empowerment of local women farmers, we are not only ensuring the sustainability of our coffee industry but also contributing to the development and prosperity of the entire region.</p>\n<p>Join us on this journey as we continue to support and motivate the incredible women who bring you the finest Green Mountain Arabica Coffee. Together, we can create a brighter and more inclusive future for all.</p>', 1, '2023-10-10 15:09:34', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/10/WhatsApp-Image-2023-10-10-at-12.41.06_8f3fea75.jpg'),
(33, 'Brewing Success: Exploring the Remarkable Benefits of Coffee', 'brewing-success-exploring-the-remarkable-benefits-of-coffee', 'Coffee, the beloved elixir of life for many, has been a subject of fascination and debate for centuries. While some may enjoy it for its rich, robust flavor, others savor it for the much-needed energy boost it provides…', '<p>Coffee, the beloved elixir of life for many, has been a subject of fascination and debate for centuries. While some may enjoy it for its rich, robust flavor, others savor it for the much-needed energy boost it provides. Beyond its delightful taste and stimulating effects, coffee offers a myriad of health benefits that may surprise you. In this blog, we\'ll delve into the world of coffee and uncover its remarkable advantages for both your body and mind.</p><ol>\n<li>Enhanced Cognitive Function: Coffee is renowned for its ability to improve mental alertness and concentration. The caffeine in coffee acts as a stimulant, enhancing neurotransmitter function in the brain. This can lead to improved focus, better problem-solving skills, and enhanced cognitive performance.</li>\n<li>Antioxidant Powerhouse: Coffee is loaded with antioxidants, which help combat free radicals in the body. These antioxidants can reduce the risk of chronic diseases and may even contribute to a longer lifespan. Coffee is one of the most significant sources of antioxidants in the Western diet.</li>\n<li>Reduced Risk of Certain Diseases: Numerous studies have suggested that coffee consumption is associated with a lower risk of various diseases. These include Parkinson\'s disease, Alzheimer\'s disease, type 2 diabetes, and certain types of cancer, such as liver and colorectal cancer.</li>\n<li>Improved Physical Performance: Caffeine in coffee is a natural ergogenic aid, meaning it can enhance physical performance. It increases the release of adrenaline, which can improve endurance and strength during physical activities. Many athletes rely on a cup of coffee to boost their workouts.</li>\n<li>Mood Elevation: Coffee doesn\'t just wake you up; it can also lift your mood. Caffeine triggers the release of dopamine, a neurotransmitter associated with pleasure and happiness. This is why coffee is often linked to a sense of well-being and reduced risk of depression.</li>\n<li>Enhanced Metabolism and Fat Burning: Coffee can rev up your metabolism, making it easier for your body to burn fat. Caffeine is a common ingredient in many weight loss supplements due to its ability to increase the rate at which your body burns calories.</li>\n<li>Protection for the Liver: Regular coffee consumption has been linked to a lower risk of liver diseases, including cirrhosis and fatty liver disease. It can also reduce the risk of liver cancer.</li>\n<li>Social and Psychological Benefits: Coffee serves as a social lubricant, fostering connections and conversations among friends, family, and colleagues. The act of brewing and savoring a cup of coffee can provide a comforting and enjoyable ritual, contributing to overall well-being.</li></ol>\n<p>Coffee is more than just a morning ritual or a pick-me-up; it\'s a beverage with a host of health benefits. From improved cognitive function to reduced risk of diseases and enhanced mood, coffee has a lot to offer. However, it\'s important to enjoy it in moderation, as excessive caffeine intake can lead to adverse effects. So, raise your cup to the many benefits of coffee, and savor its delightful taste while reaping the rewards it offers to your body and mind.</p>', 1, '2023-10-05 13:35:12', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/10/pexels-burst-374147.jpg'),
(34, 'Brewing Success: How to Produce Quality Coffee and Attract Customers for Your Coffee Business', 'brewing-success-how-to-produce-quality-coffee-and-attract-customers-for-your-coffee-business', 'Coffee is more than just a beverage; it\'s a daily ritual for millions of people around the world. For coffee businesses, producing quality coffee and attracting customers are the keys to success. In this blog, we\'ll expl…', '<p>Coffee is more than just a beverage; it\'s a daily ritual for millions of people around the world. For coffee businesses, producing quality coffee and attracting customers are the keys to success. In this blog, we\'ll explore the steps to create top-notch coffee and effective strategies to draw customers to your coffee business.</p>\n<p><strong>Part 1: Crafting Quality Coffee</strong></p><ol>\n<li><strong>Start with Fresh Beans</strong>: The foundation of great coffee is fresh, high-quality beans. Source beans from reputable suppliers, and ensure they are stored properly in a cool, dark place.</li>\n<li><strong>Invest in Quality Equipment</strong>: Quality coffee starts with quality equipment. Invest in a good grinder, espresso machine, and brewing tools. Regularly maintain and clean your equipment to avoid any flavor contamination.</li>\n<li><strong>Perfect Your Brewing Technique</strong>: Pay attention to the brewing process. Understand water temperature, extraction time, and grind size to create the ideal cup of coffee. Consistency is key.</li>\n<li><strong>Experiment and Innovate</strong>: Don\'t be afraid to experiment with different brewing methods and coffee blends. Offering unique and seasonal options can pique customer interest.</li>\n<li><strong>Freshness Matters</strong>: Coffee tastes best when it\'s fresh. Offer freshly brewed coffee and ensure that beans are roasted shortly before use. Encourage customers to enjoy their coffee on-site to experience the freshness.</li></ol>\n<p><strong>Part 2: Attracting Customers</strong></p><ol>\n<li><strong>Create a Welcoming Ambiance</strong>: The atmosphere in your coffee shop matters. Design a space that is inviting and comfortable. Consider factors like lighting, seating, and music to create the perfect ambiance.</li>\n<li><strong>Quality Customer Service</strong>: Exceptional service can set your coffee business apart. Train your staff to be knowledgeable about coffee and provide friendly, efficient service.</li>\n<li><strong>Digital Presence</strong>: Establish a strong online presence. Create a website and maintain active social media profiles. Share photos of your coffee, customer reviews, and engage with your audience.</li>\n<li><strong>Offer Loyalty Programs</strong>: Encourage repeat customers by implementing loyalty programs. Offer discounts, free drinks, or exclusive access to new blends for loyal patrons.</li>\n<li><strong>Host Events and Tastings</strong>: Organize events like coffee tastings, workshops, or live music nights. These activities not only attract customers but also build a sense of community around your coffee business.</li>\n<li><strong>Collaborate with Local Businesses</strong>: Partner with nearby businesses to cross-promote each other. For example, offer discounts to customers who visit a neighboring bakery or bookstore.</li>\n<li><strong>Engage in Sustainable Practices</strong>: Many customers appreciate businesses that care for the environment. Implement eco-friendly practices, such as using biodegradable cups and supporting fair trade coffee.</li>\n<li><strong>Listen to Customer Feedback</strong>: Pay attention to customer feedback and reviews. Use constructive criticism to improve your offerings and show customers that you value their opinions.</li></ol>\n<p>Producing quality coffee and attracting customers go hand in hand in the coffee business. By focusing on the art of coffee-making and implementing effective customer engagement strategies, you can create a thriving coffee business that not only serves exceptional coffee but also fosters a loyal customer base. Remember, it\'s not just about the coffee; it\'s about the experience you provide to your customers that will keep them coming back for more.</p>', 1, '2023-09-29 09:21:08', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/09/Gmac_15-1.jpg'),
(35, 'Nurturing Our Coffee Seedlings: A Journey of Growth', 'nurturing-our-coffee-seedlings-a-journey-of-growth', 'Nurturing Our Coffee Seedlings: A Journey of Growth Hey there, coffee enthusiasts! ☕️ At our coffee farm, we\'re on an exciting journey to nurture our precious coffee seedlings. It\'s a labor of love, patience, and dedicat…', '<p><strong>Nurturing Our Coffee Seedlings: A Journey of Growth</strong></p>\n<p>Hey there, coffee enthusiasts! ☕️</p>\n<p>At our coffee farm, we\'re on an exciting journey to nurture our precious coffee seedlings. It\'s a labor of love, patience, and dedication that we\'re thrilled to share with you. Join us as we take you behind the scenes of our coffee seedling care and growth process.</p>\n<p><strong>1. Selecting the Finest Seeds</strong></p>\n<p>The journey begins with selecting the finest coffee seeds. We carefully handpick seeds from the healthiest coffee cherries, ensuring that each one has the potential to become a flavorful, aromatic coffee tree.</p>\n<p><strong>2. The Perfect Nursery</strong></p>\n<p>Our coffee seedlings are raised in a meticulously maintained nursery. We provide them with just the right amount of sunlight, water, and nutrient-rich soil to promote strong root development and vigorous growth.</p>\n<p><strong>3. TLC: Tender Loving Care</strong></p>\n<p>Every coffee seedling gets individual attention. We check for pests, ensure they\'re well-hydrated, and protect them from harsh weather conditions. Our team is always there to lend a helping hand.</p>\n<p><strong>4. The Miracle of Growth</strong></p>\n<p>Watching these seedlings sprout and grow is a true marvel. Their leaves unfurl, and their roots reach deeper into the earth with each passing day, promising a future filled with delicious coffee beans.</p>\n<p><strong>5. Sustainable Practices</strong></p>\n<p>We\'re committed to sustainable farming practices. Our seedlings benefit from organic fertilizers and natural pest control methods, ensuring that they grow in harmony with the environment.</p>\n<p><strong>6. Connecting with Our Community</strong></p>\n<p>We believe in community engagement and sharing knowledge. We regularly host workshops and invite fellow coffee lovers to join us in our journey, fostering a deeper appreciation for coffee cultivation.</p>\n<p>Now, how about joining us on this journey? Follow us on Instagram for more updates and stunning visuals of our coffee seedlings\' growth:</p>\n<p><strong>#CoffeeSeedlings #CoffeeFarmLife #SustainableCoffee #NurturingNature #CoffeeLovers #FarmToCup #CoffeeJourney #FarmLife #CoffeeMagic #CaffeineChronicles #SeedlingCare</strong></p>\n<p>Stay tuned as we continue to nurture our coffee seedlings and bring you closer to the magic of coffee cultivation. Your support means the world to us as we strive to produce the finest coffee for you to savor. ☕️💚🌱</p>\n<p>#CoffeeFarm #CoffeeSeedlings #SustainableFarming #FarmLife #CoffeeLovers #NatureLovers #CoffeeMagic #GreenThumb #CoffeeCultivation #InstagramCoffee #CoffeeJourney</p>', 1, '2023-09-20 15:00:57', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/09/RDU1632.jpg'),
(36, 'The Art of Coffee Sorting: From Raw Beans to a Cup of Perfection', 'the-art-of-coffee-sorting-from-raw-beans-to-a-cup-of-perfection', 'Coffee, a beloved elixir that graces our mornings and fuels our days, embarks on a remarkable journey from the plantations to our cups. At the heart of this journey lies a crucial yet often overlooked step: coffee sortin…', '<p>Coffee, a beloved elixir that graces our mornings and fuels our days, embarks on a remarkable journey from the plantations to our cups. At the heart of this journey lies a crucial yet often overlooked step: coffee sorting. In this blog, we delve into the intricate process that transforms freshly washed coffee beans into a cup of liquid art, and the energy and dedication it takes to achieve that perfect brew.</p>\n<p><strong>The Labor-Intensive Task of Sorting</strong></p>\n<p>Imagine a scene: a woman hunched over a table, her hands meticulously sifting through a cascade of washed coffee beans. Each bean is examined, evaluated, and sorted with care. What seems like a simple task at a glance is, in fact, a labor-intensive process that requires an unwavering commitment to quality. Imperfections, defects, and any unwanted elements are carefully removed, ensuring that only the finest beans remain.</p>\n<p><strong>The Energy Behind the Quality</strong></p>\n<p>Sorting coffee demands not only physical energy but also an acute sensory awareness. The sorter\'s trained eyes can discern nuances that might escape an untrained observer—tiny blemishes, irregular shapes, and variations in color that could impact the final cup\'s flavor. This intricate task embodies a dedication to perfection, as every bean that passes through the hands of the sorter contributes to the blend\'s overall quality.</p>\n<p><strong>From Sorting to Sipping: Unveiling the Transformation</strong></p>\n<p>The magic of coffee sorting culminates in that satisfying moment when the first sip graces our lips. As we take in the rich aroma and savor the complex flavors, it\'s easy to forget the journey that led to this point. The woman\'s diligent efforts, her commitment to ensuring only the best beans make it through, have set the stage for a symphony of tastes that dance on our taste buds.</p>\n<p><strong>A Cup That Tells a Tale</strong></p>\n<p>Coffee sorting is more than a task; it\'s an art that brings together the dedication of farmers, sorters, roasters, and baristas. It\'s a tale of collaboration, where each link in the chain contributes to the final masterpiece—the cup of coffee that warms our hearts and invigorates our spirits. This cup tells the story of passion, attention to detail, and the pursuit of excellence.</p>\n<p><strong>Join Us on the Journey</strong></p>\n<p>If the world behind your morning cup of coffee intrigues you, if you find yourself captivated by the dedication and energy poured into each bean, then come along on this journey with us. Swipe to the next image and witness the transformation from raw beans to a beautifully brewed cup. If you\'re as fascinated as we are, reach out to us via DM. Let\'s explore this world together and celebrate the remarkable process that turns a humble bean into a masterpiece of flavor and aroma. </p>\n<p>The journey from coffee plantations to our mugs is a symphony of hard work and dedication. Coffee sorting, in particular, stands as a testament to the energy and passion invested in every cup. As you sip your next coffee, take a moment to appreciate the artistry that brings it to life—one sorted bean at a time.</p>', 1, '2023-08-28 14:10:39', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/08/M4T6968-1.jpg'),
(37, 'A Beginner\'s Guide to Coffee Cupping: Steps and Techniques', 'a-beginners-guide-to-coffee-cupping-steps-and-techniques', 'Coffee cupping is a valuable practice used by coffee professionals and enthusiasts to evaluate and appreciate the various flavors, aromas, and nuances of different coffee beans. Whether you\'re a coffee connoisseur, a cof…', '<p>Coffee cupping is a valuable practice used by coffee professionals and enthusiasts to evaluate and appreciate the various flavors, aromas, and nuances of different coffee beans. Whether you\'re a coffee connoisseur, a coffee shop owner, or simply someone curious about the art of coffee tasting, this blog post will walk you through the essential steps of a coffee cupping session.</p>\n<p>Step 1: Gathering the Tools: To conduct a successful coffee cupping, you\'ll need the following tools:</p><ol>\n<li>Freshly roasted coffee beans: Select a variety of coffee beans representing different origins, roast levels, and flavor profiles.</li>\n<li>Grinder: Use a burr grinder to grind the coffee beans just before cupping.</li>\n<li>Cups: Choose specialized coffee cupping cups, which are typically shallow, cylindrical, and made of ceramic or glass.</li>\n<li>Cupping spoons: Use long-handled, shallow spoons specifically designed for coffee cupping.</li>\n<li>Water: Provide clean, preferably filtered water at a controlled temperature for brewing and rinsing the spoons.</li>\n<li>Cupping sheets: Prepare cupping score sheets to record your observations during the tasting process.</li></ol>\n<p>Step 2: Bean Evaluation: Before the cupping process, visually inspect and evaluate the coffee beans. Look for the size, shape, color, and uniformity of the beans. Additionally, take note of any defects or irregularities that may impact the cupping experience.</p>\n<p>Step 3: Grinding the Beans: Grind the coffee beans uniformly, ensuring a consistent particle size. It\'s recommended to use a medium-coarse grind for cupping. Clean the grinder between different coffee samples to prevent cross-contamination of flavors.</p>\n<p>Step 4: Aroma Assessment: Take a moment to smell the dry, freshly ground coffee. Inhale deeply to detect the aroma and make note of the initial impressions. Consider the fragrance, intensity, and specific notes that come to mind. This step helps you understand the aromatic qualities of each coffee sample.</p>\n<p>Step 5: Wetting the Grounds: Add a precise amount of hot water to each cup, allowing the coffee to steep for several minutes. The ratio typically used is 8.25 grams of coffee to 150 milliliters of water. Ensure the water temperature is between 195°F and 205°F (90°C to 96°C) for optimal extraction.</p>\n<p>Step 6: Breaking the Crust: After steeping, use a spoon to break the crust that forms on the surface of each cup. As you break the crust, inhale the aromas that are released. This step allows you to experience the coffee\'s fragrance in a more concentrated form.</p>\n<p>Step 7: Evaluating Flavor and Body: Using a spoon, carefully scoop a small amount of coffee from the cup, taking care to remove any lingering foam or grounds. Slurp the coffee from the spoon, allowing it to coat your entire palate. Pay attention to the coffee\'s acidity, sweetness, bitterness, and other flavor attributes. Consider the body, or mouthfeel, which describes the texture and weight of the coffee.</p>\n<p>Step 8: Scoring and Recording: Record your observations on the cupping score sheets, noting the aroma, flavor, acidity, body, and any other attributes you identify. Assign scores or descriptors based on your personal assessment.</p>\n<p>Step 9: Comparisons and Discussions: After evaluating each coffee sample individually, compare and contrast the flavors and characteristics across different cups. Engage in discussions with fellow cuppers to share insights, opinions, and preferences.</p>\n<p>Conclusion: Coffee cupping is a valuable tool for understanding and appreciating the wide array of flavors and qualities found in coffee beans. By following these steps and engaging in regular cupping sessions, you\'ll deepen your knowledge of coffee and enhance your ability to select and appreciate the perfect cup. Happy cupping!</p>', 1, '2023-07-24 09:00:00', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/07/350455461_971474240703511_9152645934913002482_n.jpg'),
(38, 'A Successful Harvest Season at GMAC: Celebrating Green Mountain Arabica Coffee', 'a-successful-harvest-season-at-gmac-celebrating-green-mountain-arabica-coffee', 'As the coffee harvesting season comes to a close, we at GMAC (Green Mountain Arabica Coffee) are delighted to share the news of a fruitful and successful season. Our dedicated team of farmers has worked tirelessly to cul…', '<p>As the coffee harvesting season comes to a close, we at GMAC (Green Mountain Arabica Coffee) are delighted to share the news of a fruitful and successful season. Our dedicated team of farmers has worked tirelessly to cultivate and nurture our high-quality Arabica coffee beans. Join us as we reflect on the highlights of this season and celebrate the exquisite taste and aroma of our coffee.</p><ol>\n<li>Bountiful Harvest: The 2023 coffee harvesting season at GMAC has been nothing short of remarkable. Our coffee plants flourished under optimal growing conditions, resulting in a bountiful yield of superior Arabica coffee beans. Our commitment to sustainable farming practices, including shade-grown cultivation, organic fertilizers, and water conservation, played a crucial role in achieving such outstanding results.</li>\n<li>Meticulous Handpicking: At GMAC, we take great pride in our meticulous handpicking process. Every coffee cherry is carefully inspected and selectively harvested at its peak ripeness. This labor-intensive method ensures that only the finest beans make their way into your cup. Our skilled workers\' expertise and attention to detail contribute to the superior taste and quality that GMAC coffee is renowned for.</li>\n<li>Sustainable Practices: Environmental responsibility lies at the heart of GMAC\'s coffee production. We are committed to preserving the natural beauty of our coffee-growing region and minimizing our ecological footprint. Through sustainable farming practices and the use of renewable energy sources, we aim to reduce our impact on the environment. By choosing GMAC coffee, you are supporting a sustainable and eco-friendly approach to coffee cultivation.</li>\n<li>Exceptional Quality Control: Maintaining consistent quality is of paramount importance to us at GMAC. We have implemented stringent quality control measures at every stage of the coffee production process. From the initial cultivation to the final packaging, our team ensures that only the highest-grade beans meet our rigorous standards. We believe that this commitment to excellence is what sets GMAC coffee apart and guarantees a delightful coffee experience for our customers.</li>\n<li>Community Impact: At GMAC, we value the close-knit relationship we have with our local community. As a responsible business, we strive to create a positive impact on the lives of our farmers and their families. By providing fair wages and access to education and healthcare, we aim to uplift the entire community. When you choose GMAC coffee, you are supporting a company that prioritizes social responsibility and the well-being of its employees.</li></ol>\n<p>As the curtains draw on another successful coffee harvesting season at GMAC, we extend our heartfelt gratitude to our dedicated team, committed partners, and loyal customers. Our passion for producing exceptional Arabica coffee continues to drive us forward. We invite you to savor the rich flavors and aromas of GMAC coffee, knowing that each sip represents a labor of love, sustainability, and a commitment to excellence. Together, let\'s raise a cup to celebrate the joys of Green Mountain Arabica Coffee!</p>', 1, '2023-07-11 05:35:50', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/07/RDU1684-07.30.10.jpg'),
(39, 'GMAC\'s Remarkable Experience at China Coffee Expo: Cultivating New Relationships and Enhancing Industry Expertise', 'gmacs-remarkable-experience-at-china-coffee-expo-cultivating-new-relationships-and-enhancing-industry-expertise-in-china', 'GMAC (Green Mountain Arabica Coffee) recently had the privilege of attending the highly anticipated China Coffee Expo, a prominent international event showcasing the finest coffee products and fostering industry collabor…', '<p>GMAC (Green Mountain Arabica Coffee) recently had the privilege of attending the highly anticipated China Coffee Expo, a prominent international event showcasing the finest coffee products and fostering industry collaboration. Our participation at the expo proved to be an exceptional opportunity to connect with potential clients, gain valuable insights, and participate in various training programs. In this blog post, we will highlight the remarkable experience GMAC had at the China Coffee Expo, emphasizing the significance of cultivating new relationships and enhancing our industry expertise.</p><figure class=\"wp-block-image size-full\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/07/WhatsApp-Image-2023-07-10-at-7.33.59-AM-1.jpeg\" alt=\"Niyonsaba jeanne - GMac(Green Mountain Arabica Coffee)\" class=\"wp-image-16211\"/></figure>\n<p>Connecting with Potential Clients: One of the primary goals of GMAC\'s presence at the China Coffee Expo was to forge new partnerships and establish relationships with potential clients. The expo served as a meeting point for coffee enthusiasts, industry professionals, and coffee businesses from around the world. By showcasing our premium Arabica coffee products, we attracted the attention of numerous visitors who were keen to explore new coffee offerings. The engaging conversations and interactions allowed us to showcase the unique features and exceptional quality of GMAC\'s coffees, generating interest and opening doors for potential collaborations.</p>\n<p>Exploring Market Trends and Insights: Attending the China Coffee Expo provided GMAC with an invaluable opportunity to gain deeper insights into the latest market trends, innovations, and consumer preferences within the Chinese coffee industry. The event featured a series of seminars, panel discussions, and presentations from industry experts, allowing us to stay at the forefront of emerging coffee trends. By attending these sessions, we enhanced our understanding of the evolving Chinese coffee market, enabling us to tailor our products and strategies to meet the specific needs and demands of Chinese consumers.</p>\n<p>Participating in Training Programs: GMAC recognizes the importance of continuous learning and improvement to stay competitive in the coffee industry. The China Coffee Expo offered a range of training programs, workshops, and demonstrations designed to enhance participants\' knowledge and skills. Our team eagerly participated in these sessions, which covered topics such as coffee brewing techniques, cupping sessions, and sustainability practices. By engaging in these training programs, we not only expanded our expertise but also strengthened our commitment to delivering exceptional coffee experiences while prioritizing environmental sustainability.</p>\n<p>Showcasing GMAC\'s Commitment to Sustainability: The China Coffee Expo provided GMAC with a platform to highlight our unwavering commitment to sustainability. As an environmentally conscious coffee company, we shared our sustainable farming practices, fair trade initiatives, and efforts to reduce our carbon footprint. Through engaging presentations and discussions, we not only educated attendees about the importance of sustainable coffee production but also inspired other industry players to adopt similar practices. The expo served as a hub for sustainability-focused conversations, enabling us to connect with like-minded individuals and organizations and explore potential collaborations in this domain.</p>', 1, '2023-07-10 05:36:28', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/07/WhatsApp-Image-2023-07-10-at-7.33.59-AM.jpeg'),
(40, 'Empowering Communities and Building Sustainable Development: Robobank Netherland Funds Our Coffee Hulling Industry Project', 'empowering-communities-and-building-sustainable-development-rab-bank-switzerland-funds-our-coffee-hulling-industry-project', 'We are thrilled to announce that the Hulling Coffee Industry Project, which aims to bring sustainable development and community empowerment to a local area, has received funding from RAB Bank Netherland.GMAC The project…', '<p>We are thrilled to announce that the Hulling Coffee Industry Project, which aims to bring sustainable development and community empowerment to a local area, has received funding from RAB Bank Netherland.</p><figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/04/Gmacc_32-1024x683.jpg\" alt=\"\" class=\"wp-image-16201\"/><figcaption class=\"wp-element-caption\">GMAC</figcaption></figure></figure>\n<p>The project focuses on building an industry for hulling coffee, which will not only provide new job opportunities for the community, but also increase the value of their coffee production. The project has been progressing well, and the Robobank Netherland Project Manager and Program Manager for Africa recently visited to check on its progress.</p>\n<p>During their visit, they were accompanied by a representative from the United Nations Capital Development Fund (UNCDF), which is supporting the project as well. Together, they observed the construction of the factory and the training of the local workers who will be operating it.</p><figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/04/401A9046_1-1024x683.jpg\" alt=\"\" class=\"wp-image-16202\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/04/401A9076_1-1024x683.jpg\" alt=\"\" class=\"wp-image-16203\"/></figure></figure>\n<p>The partnership between Robobank Netherland and UNCDF has been instrumental in making this project a reality. Through their collaboration, the Hulling Coffee Industry Project is not only creating new economic opportunities, but also contributing to the sustainable development of the local community.</p><figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/04/Gmacc_29-1024x683.jpg\" alt=\"\" class=\"wp-image-16199\"/></figure></figure>\n<p>We are proud to be a part of this project and grateful for the support of Robobank Netherland and UNCDF. We look forward to seeing the positive impact it will have on the community and the wider coffee industry.</p>', 1, '2023-04-28 11:21:19', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/04/Gmacc_25.jpg'),
(41, 'It\'s that time of the year again – coffee harvesting season has recently begun!', 'its-that-time-of-the-year-again-coffee-harvesting-season-has-recently-begun', 'The sweet aroma of freshly picked coffee beans fills the air, and farmers all around the world are busy at work collecting the fruits of their labor. Here at Green Mountain Arabica Coffee (GMAC), we\'re excited to be a pa…', '<p>The sweet aroma of freshly picked coffee beans fills the air, and farmers all around the world are busy at work collecting the fruits of their labor. Here at Green Mountain Arabica Coffee (GMAC), we\'re excited to be a part of this annual tradition and are working hard to prepare our coffee for the world to enjoy.</p>\n<p>At GMAC, we take pride in producing some of the finest Arabica coffee beans in the world. Our farmers carefully cultivate and tend to our coffee plants throughout the year, ensuring that they receive the right amount of sunlight, water, and nutrients. When it\'s time for harvest, our team of skilled workers handpick each bean with care, ensuring that only the ripest and most flavorful beans are selected.</p><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/P9A0060-1024x576.jpg\" alt=\" Coffee Sorting - GMAC \" class=\"wp-image-16177\"/><figcaption class=\"wp-element-caption\"> Coffee Sorting - GMAC </figcaption></figure>\n<p>Once the beans are harvested, they\'re processed using the latest techniques to ensure that their unique flavors and aromas are preserved. At GMAC, we use a combination of wet and dry processing methods to create our signature flavor profile, which is rich and smooth with hints of chocolate and caramel.</p>\n<p>But our work doesn\'t stop there. After the beans are processed, they\'re roasted to perfection in small batches by our team of expert roasters. We believe that the roasting process is just as important as the harvesting and processing stages, as it\'s where the true flavor of the coffee comes to life. Our roasters use a variety of techniques to create the perfect roast for each batch of beans, ensuring that the flavor is consistent and delicious every time.</p><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/Gmac_3-1024x576.jpg\" alt=\"Dried Natural Coffee - GMAC\" class=\"wp-image-16178\"/><figcaption class=\"wp-element-caption\">Dried Natural Coffee - GMAC</figcaption></figure>\n<p>Finally, our coffee is packaged and shipped to coffee lovers around the world, who can enjoy the rich, smooth taste of GMAC\'s Arabica coffee in the comfort of their own homes. We take great care to ensure that our coffee is sustainably sourced and ethically produced, so you can enjoy each cup with a clear conscience.</p><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/Gmaccc_15-1024x576.jpg\" alt=\"Not Yet Drying Natural Coffee - GMAC\" class=\"wp-image-16179\"/><figcaption class=\"wp-element-caption\">Not Yet Drying Natural Coffee - GMAC</figcaption></figure>\n<p>As the coffee harvesting season continues, we at GMAC are excited to bring you the finest Arabica coffee beans that nature has to offer. Whether you\'re a coffee connoisseur or just enjoy a good cup of joe, we invite you to try our coffee and experience the unique flavors and aromas that make GMAC\'s coffee so special. Cheers to a great coffee harvesting season!</p>', 1, '2023-03-31 06:34:31', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/03/P9A0047.jpg'),
(42, 'Insights from the #AgriTech International Agricultural Exhibition 2023 in Qatar', 'insights-from-the-agritech-international-agricultural-exhibition-2023-in-qatar', 'Last week, I had the opportunity to attend the #AgriTech Coffee Farmers Meeting in Qatar. It was a great event where coffee farmers from different parts of the world came together to discuss their experiences, share know…', '<p>Last week, I had the opportunity to attend the #AgriTech Coffee Farmers Meeting in Qatar. It was a great event where coffee farmers from different parts of the world came together to discuss their experiences, share knowledge, and explore new technologies that can help them grow their businesses. Here are some of the key insights I gained from the event.</p><ol>\n<li><strong>Climate change is a major challenge for coffee farmers.</strong><ul></ul></li></ol>\n<p>One of the main challenges that coffee farmers face today is climate change. Changes in temperature and rainfall patterns can have a significant impact on coffee production, and farmers need to adapt to these changes in order to maintain their crops. The coffee farmers at the #AgriTech meeting discussed the different strategies they use to deal with climate change, including planting shade trees, improving soil health, and using irrigation systems.</p><ol start=\"2\">\n<li><strong>Technology can help farmers increase their yields and improve their livelihoods.</strong></li></ol>\n<p>Technology is playing an increasingly important role in agriculture, and coffee farming is no exception. The coffee farmers at the #AgriTech meeting talked about the different technologies they use to improve their yields and increase their income. These technologies include precision farming tools, such as drones and sensors, which can help farmers monitor their crops and optimize their inputs. They also discussed the use of mobile apps to track coffee prices and market trends, and the importance of social media in connecting with customers and promoting their products.</p><ol start=\"3\">\n<li><strong>Collaboration is key to the success of coffee farming communities.</strong></li></ol>\n<p>The coffee farmers at the #AgriTech meeting stressed the importance of collaboration and knowledge-sharing among coffee farming communities. By working together, farmers can pool their resources, share best practices, and support each other in times of need. The meeting provided a great opportunity for farmers to connect with each other and learn from each other\'s experiences.</p>\n<p>In conclusion, the #AgriTech Coffee Farmers Meeting in Qatar was a great event that highlighted the challenges and opportunities facing coffee farmers today. By sharing their experiences, knowledge, and ideas, farmers can work together to build a more sustainable and profitable coffee industry.</p>\n<p>Images:</p><figure class=\"wp-block-gallery has-nested-images columns-default is-cropped\"><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/photo_5823369152910441858_y-1024x682.jpg\" alt=\"\" class=\"wp-image-16165\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/photo_5823369152910441859_y-1024x682.jpg\" alt=\"\" class=\"wp-image-16163\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/photo_5823369152910441860_y-1024x682.jpg\" alt=\"\" class=\"wp-image-16170\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/photo_5823369152910441867_y-1024x682.jpg\" alt=\"\" class=\"wp-image-16168\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/photo_5823369152910441874_y-1024x682.jpg\" alt=\"\" class=\"wp-image-16162\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/photo_5823369152910441876_y-1-1024x682.jpg\" alt=\"\" class=\"wp-image-16172\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/photo_5823369152910441877_y-1-1024x682.jpg\" alt=\"\" class=\"wp-image-16161\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/photo_5823369152910441879_y-1024x682.jpg\" alt=\"\" class=\"wp-image-16166\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/photo_5823369152910441880_y-1-1024x682.jpg\" alt=\"\" class=\"wp-image-16173\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/photo_5823369152910441881_y-1024x682.jpg\" alt=\"\" class=\"wp-image-16167\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/photo_5823369152910441883_y-1-1024x682.jpg\" alt=\"\" class=\"wp-image-16164\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/photo_5823369152910441884_y-1024x682.jpg\" alt=\"\" class=\"wp-image-16171\"/></figure><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/03/photo_5823369152910441885_y-1-1024x682.jpg\" alt=\"\" class=\"wp-image-16169\"/></figure></figure>', 1, '2023-03-28 07:13:28', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/03/photo_5823369152910441880_y.jpg'),
(43, 'A Guide to Common Coffee Pests & Diseases', 'a-guide-to-common-coffee-pests-diseases', 'Pests and diseases can ruin your coffee crop. An infestation or outbreak that is badly handled can mean financial hardship or even devastation. But do you know which pests and diseases are the greatest threats? And how d…', '<p>Pests and diseases can ruin your coffee crop. An infestation or outbreak that is badly handled can mean financial hardship or even devastation. But do you know which pests and diseases are the greatest threats? And how do you identify them?</p>\n<p>Let’s take a look at coffee pests and diseases to better understand what they are and how to handle them.</p><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/01/pexels-michael-burrows-7125492-22-1024x683.jpg\" alt=\"\" class=\"wp-image-16004\"/><figcaption class=\"wp-element-caption\"><br>source: pexels.com</figcaption></figure>\n<h2><strong>WHAT CAUSES DISEASES & ATTRACTS PESTS</strong></h2>\n<p>Like any crop, the coffee plant is vulnerable to pests and diseases. A 2012 <a href=\"https://www.researchgate.net/publication/259574741_Impact_of_field_pests_and_diseases_on_coffee_quality\" target=\"_blank\" rel=\"noreferrer noopener\">report</a> by Fabienne Ribeyre, a researcher at French agricultural research center CIRAD, states that “most coffee diseases are caused by pathogenic fungi and less frequently by bacteria and viruses.”</p>\n<p>“Root rot disease, rusts, and coffee berry disease can attack healthy trees without any particular physiological weakness, whereas most of the other diseases of economic importance only occur in trees that are physiologically weakened,” it says.</p>\n<p>But some factors make a coffee crop more vulnerable to infestation or outbreak. Adriana Villanueva is a co-founder of <a href=\"http://inconexus.com/\" target=\"_blank\" rel=\"noreferrer noopener\">Inconexus</a>, a Colombian coffee exporter. She tells me that the the following factors influence the incidence of pests and diseases.</p><ul>\n<li><strong><em>Genetics</em></strong></li></ul>\n<p>Some varieties of coffee are more vulnerable to disease than others. For example, Bourbon Pointu/Laurina is known to be very susceptible to leaf rust.</p><ul>\n<li><strong><em>Environmental Conditions</em></strong></li></ul>\n<p>Coffee is produced in many countries and there are pests and diseases in every area. But the specific pests and diseases vary dependent on environmental conditions. For example, the coffee borer beetle thrives in humid conditions.</p>\n<p>So when Arabica is grown at lower altitudes, the relative warmth and humidity puts it at increased risk of coffee berry borer. But even if the season is inhospitably dry, the insects can hide in the cherries until the first rains, when they emerge en masse and create devastation.</p>\n<p>And some diseases are almost universal. Coffee leaf rust is a fungus that has become one of the biggest threats to coffee around the world. It is present in almost every coffee-producing country, regardless of local environmental conditions.</p><figure class=\"wp-block-image aligncenter size-full\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/01/nurseries.jpg\" alt=\"\" class=\"wp-image-16005\"/><figcaption class=\"wp-element-caption\">Defected Nurseries-source: perfectdailygrind.com</figcaption></figure><ul>\n<li><strong><em>Crop Management</em></strong></li></ul>\n<p>Good agricultural understanding can make all the difference in the control of pests and diseases. Farmers rely on productive and resilient plants to remain competitive. If crops are managed poorly, it could have a serious impact on yield and profit.</p>\n<p>For example, damaged coffee plants can be more susceptible to fungal infection and improper fertilization can cause structural weakness. And even something as small as leaving fallen leaves on the ground can be a problem – it increases the likelihood of mold and can provide cover for pests.</p><ul>\n<li><strong><em>Economics</em></strong></li></ul>\n<p>Producers who do not make enough money to invest in their farms are more likely to suffer from pests and diseases. This can be self-perpetuating. If a farmer can’t afford fertilizer, new plants, or pesticides, they may be more affected by pests and diseases, and produce a low yield. This in turn means they may not have the resources to invest in next year’s crops and the cycle continues.</p>\n<h2><strong>WHICH PESTS & DISEASES SHOULD YOU WATCH FOR?</strong></h2>\n<p>Although there are hundreds of pests and many diseases that can affect coffee plants, some are more prevalent than others. Ribeyre’s report says that there are more than 900 species of insects, various other pests (including microscopic parasites, molluscs, birds, and mammals), and a large number of diseases that attack coffee crops.</p>\n<p>But it says that “Most pests and diseases are spatially distributed, with many of them restricted to only one continent. Only a small number of pests are widespread throughout the tropics.”</p>\n<p>It also explains that the majority of these pests have been accidentally spread through infested coffee shipments. Let’s take a closer look at some of the pests and diseases that affect coffee.</p>\n<h2><strong>COMMON COFFEE PESTS</strong></h2>\n<p>Insects generally weaken coffee beans and reduce density. The bites from insects also open coffee plants up to secondary infection from fungi and other microorganisms. Infestation by insects not only reduces yield, but can have a considerable effect on coffee profile, with reduction in quality of flavor and aroma.</p>\n<p>These are some of the pests you’re likely to encounter on a coffee farm.</p><ul>\n<li><strong><em>Coffee Berry Borer</em></strong></li></ul>\n<p>These tiny black beetles are present in almost all coffee-producing countries, where they burrow inside coffee cherries. They are very difficult to manage with insecticides because they are protected by the cherries.</p>\n<p>The insects spread worldwide from Africa alongside coffee crops as far back as the 16th century. Café de Colombia <a rel=\"noreferrer noopener\" href=\"http://www.cafedecolombia.com/particulares/en/sobre_el_cafe/el_cafe/manejo_agronomico/\" target=\"_blank\">states</a> that this pest has caused the most damage to coffee throughout  history.</p>\n<p>In crops affected by coffee borer beetles, yields are reduced because young bored cherries may fall prematurely and all harvested bored cherries are of lower weight.</p>\n<p>Coffee berry borer damage also affects the sensory qualities of the coffee and this reduces the commercial value of the crop. If damage is significant, it can cause the cup to taste bitter, tarry, or fermented. Berry borer damage can also cause roasts to be irregular, which has a further impact on flavor.</p><figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/01/cherry-borer-1024x680.jpg\" alt=\"\" class=\"wp-image-16006\"/><figcaption class=\"wp-element-caption\">Cherry borer- source: coffeehunter.com</figcaption></figure><ul>\n<li><strong><em>Coffee Leaf Miner</em></strong></li></ul>\n<p>Coffee leaf miners are two related species of moth – <em>Leucoptera coffeella</em>, which is prevalent in Latin America, and <em>Leucoptera caffeina</em>, which is found in African producing countries.</p>\n<p>They affect the leaves of the coffee plant. Café de Colombia <a href=\"http://www.cafedecolombia.com/particulares/en/sobre_el_cafe/el_cafe/manejo_agronomico/\" target=\"_blank\" rel=\"noreferrer noopener\">explains</a> that coffee leaf miner larvae eat coffee leaves. If several live on the same leaf, it may suffer necrosis of up to 90% of its structure. Necrosis is the death of cells and it appears as dark watery spots or brown papery patches.</p>\n<p>Defoliation affects the plant’s ability to photosynthesize. Without photosynthesis, the plant can’t grow properly. Fruit may not mature and the overall yield is likely to be much lower. If immature or dead beans make it into the final brew, they can create bitterness and astringency.</p><figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/01/Coffee-Leaf-Miner-1024x768.jpg\" alt=\"\" class=\"wp-image-16007\"/><figcaption class=\"wp-element-caption\"><strong><em>Coffee Leaf Miner</em></strong>- source: hawaiicoffeeed.com</figcaption></figure><ul>\n<li><strong><em>Mealybugs</em></strong></li></ul>\n<p>Mealybugs are a group of insects that feed on a variety of trees and plants. In coffee, they attack various parts, including branches, nodes, leaves, roots, and flower clusters.</p>\n<p>They feed on the sap of the coffee plant and secrete a sticky substance that attracts ants. This substance also leads to the formation of a black mold that covers leaves and can reduce photosynthesis.</p>\n<p>Reduced sap uptake, circulation, and photosynthesis stresses coffee plants and they tend to produce light or immature beans. This can result in astringency, a metallic taste, or bitterness in the cup.</p>\n<p>Coffee mealybugs have been found in Africa, Australia, Asia, and Central and South America.</p><ul>\n<li><strong><em>Nematodes</em></strong></li></ul>\n<p>Nematodes are microscopic worm-like parasites. There are several species that attack the root system of coffee plants and feed on their sap. Nematodes can form knots in the roots that prevent the plant from properly absorbing water and nutrients.</p>\n<p>Infestation can cause reduced roots, defoliation, and general lack of health in the plants. This can mean low yield and light beans.</p>\n<h2><strong>COMMON COFFEE DISEASES</strong></h2>\n<p>Disease is also a big threat to coffee production. These are some common conditions.</p><ul>\n<li><strong><em>Coffee Leaf Rust</em></strong></li></ul>\n<p>This fungus is a worldwide problem for coffee producers and Colombia has been battling it for generations. The BBC <a href=\"http://www.bbc.com/future/story/20171106-the-disease-that-could-change-how-we-drink-coffee\" target=\"_blank\" rel=\"noreferrer noopener\">highlights</a> that it has “the power to cripple, or even wipe out, the country’s national product, the base of one of its biggest industries, and one of its most important sources of foreign currency.”</p>\n<p>In 2012, coffee rust hit Central America hard. And over the next two years, it caused over $1 billion in damage (USAID).</p>\n<p>The disease presents as an orange rust-like dust on the underside of the coffee leaves. It is a cyclical condition that causes defoliation, just like coffee leaf miners. Wind and rain spread coffee leaf rust spores, which thrive at around 70°F/21°C. So the disease is most prevalent in Arabica grown in the warm, humid conditions of low altitudes.</p>\n<p>Because it restricts the growth of new stems, coffee leaf rust has an impact on the next year’s crop as well as significantly reducing yield in the current year.</p>\n<p>Plants affected by coffee leaf rust are unable to ripen fully and if they do fruit, will produce light beans that taste astringent. Ribeyre states that “severe attacks of coffee leaf rust may result in dead beans that transform into brown beans after the wet process. These brown beans have a sour flavor and sometimes other off-flavors.”</p><figure class=\"wp-block-image aligncenter size-full\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/01/coffee-Leaf-Rust.jpg\" alt=\"\" class=\"wp-image-16008\"/><figcaption class=\"wp-element-caption\">c<strong><em>offee Leaf Rust</em></strong> - source: bioprotectionportal.com</figcaption></figure><ul>\n<li><strong><em>Coffee Wilt</em></strong></li></ul>\n<p>Coffee wilt is a vascular disease of the coffee tree trunk that is caused by a fungus. It blocks water and sap circulation, causing leaves to fall, branches to die, and cherries to appear ripe prematurely.</p>\n<p>Using these red but immature coffee cherries can result in loss of acidity, increased bitterness, and “green” flavors in the cup.</p><ul>\n<li><strong><em>Pink Disease</em></strong></li></ul>\n<p>Pink disease is another fungal infection. It appears as webbing and pink encrustation on branches. The infected branches lose their leaves and die. <a rel=\"noreferrer noopener\" href=\"http://www.scielo.br/scielo.php?script=sci_abstract&pid=S0103-90162007000200009&lng=en&nrm=iso&tlng=en\" target=\"_blank\">It has been particularly problematic in the coffee-producing regions of Brazil.</a></p>\n<h2><strong>HOW TO PREVENT PESTS & DISEASES</strong></h2>\n<p>The best way to prevent pests and diseases is through good farm management. Variety choice, shade management, selective pesticide use, and plant nutrition are important considerations.</p>\n<p>Francisco Quezada Montenegro is an agronomist at Dinamica International Crops, a Guatemalan producer and exporter. He tells me, “Prevention can be aided by good nutrition.”</p>\n<p>He says that good nutrition makes a plant more resistant, but that preventative applications of fungicides such as Bordeaux mixture (a copper-based fungicide) are beneficial too. “The importance of copper is that it is the only fungicide that does not create resistance,” he says.</p>\n<p>And he emphasizes the importance of monitoring temperatures and humidity “to make the applications at the optimal times and have better coverage.”</p><ul>\n<li><strong><em>Pruning & Hygiene</em></strong></li></ul>\n<p>Francisco recommends an intensive pruning management schedule that means crops are pruned at least every five years. He says that after this age, they become more vulnerable to coffee rust disease.</p>\n<p>Pruning can leave unprotected wounds on the plant, which are then vulnerable to fungal infection, especially in the rainy season. Be careful to minimize damage when weeding and pruning.</p>\n<p>Also be mindful of keeping tools and equipment clean to avoid contamination between crops. These measures for the control of plant diseases are known as phytosanitation.</p><ul>\n<li><strong><em>Monitoring</em></strong></li></ul>\n<p>Monitoring is a key part of keeping coffee plants disease- and pest-free. Monitoring pests and diseases at field level helps prevent large outbreaks and minimize chemical control. Specific guidelines for monitoring vary from country to country.</p>\n<p>Jhon Espitia is a coffee producer and agronomist based in Colombia. He says that producers should record flowering and the timing and dosage of fertilization. He recommends using soil analysis to identify specific nutritional needs and scheduling specific dates for fertilization and visual monitoring.</p>\n<p>He also says that farmers should keep track of shade, rain, and humidity levels. By considering these factors, you can make an environment that encourages pests and diseases or one that helps keep them away.</p>\n<h2><strong>PESTICIDES & ALTERNATIVES</strong></h2>\n<p>If your crops are affected by pests or disease, your first thought may be of pesticides. But chemical pesticides can create water contamination, destroy the local ecosystem, and cause the death of wildlife.</p>\n<p>Ribeyre’s report says that in some cases, “use of pesticides has reduced the populations of natural enemies, leading to an increase in pest populations a few months after treatment.” There is also public awareness of the human health risks of chemical residues. And methods that avoid pesticides are also important to prevent resistance.</p>\n<p>But sometimes pesticides are needed. The same report states that “judicious use of pesticides in a well-managed integrated pest management programme will improve coffee quality.” So you don’t necessarily need to avoid them all together – just look into where other methods may work as well or better.</p>\n<p>One example of disease control without chemicals is the integrated pest management method used to manage coffee bean borers. This technique uses environmental control and predators.</p>\n<p>Café de Colombia <a href=\"http://www.cafedecolombia.com/particulares/en/sobre_el_cafe/el_cafe/manejo_agronomico/\" target=\"_blank\" rel=\"noreferrer noopener\">explains</a> that wasps are bred and then released within the coffee crops. They seek out the beetles within the cherries and eat them. A mildew is also sprinkled on the crops to destroy coffee bean borer infestations. The organization says that this method has “permitted Colombia to sustain low levels of infestation within its coffee crops to comply with its export obligations in terms of productivity and quality.”</p>\n<p><a rel=\"noreferrer noopener\" href=\"https://perfectdailygrind.com/2016/09/coffee-borer-beetle-recycled-broca-trap-costs-pennies/\" target=\"_blank\"><strong>Traps</strong></a> are another example of handling pests without pesticides.</p>\n<p>Coffee producers face many challenges. While there are many factors you can’t control, such as climate change and global economics, pests and diseases <em>can</em> be managed. Understanding pests and diseases is the first step in controlling them.</p>\n<p>So start keeping records and make sure that you are using phytosanitary techniques. Some small changes can reduce the incidence of pests and disease without major investment.</p>\n<p><em>Please note: Before implementing the advice in this article, we advise also consulting with a local technical expert, since differences in climate, soil type, varieties, processing methods, and more can affect the best practices for production and processing.</em></p>', 1, '2023-01-16 18:26:34', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/01/cherry-desease.jpg'),
(44, '5 Tips for Brewing the Perfect Cup of Coffee', '5-tips-for-brewing-the-perfect-cup-of-coffee', 'If you\'re a coffee lover like me, you know that there\'s nothing quite like a perfect cup of coffee to start your day off right. But if you\'re not a barista, you may not know all the tricks of the trade for brewing the pe…', '<p>If you\'re a coffee lover like me, you know that there\'s nothing quite like a perfect cup of coffee to start your day off right. But if you\'re not a barista, you may not know all the tricks of the trade for brewing the perfect cup. Here are five tips to help you make the most of your coffee beans and brew a delicious cup every time:</p>\n<p>1.Start with fresh, high-quality beans. Good coffee starts with good beans, so it\'s worth it to invest in a high-quality roast from a reputable source. Look for beans that are roasted within the past week or two, and try to avoid pre-ground coffee if possible, as it can go stale quickly.</p><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/01/pexels-adam-lukac-773958-1024x683.jpg\" alt=\"\" class=\"wp-image-15993\"/><figcaption class=\"wp-element-caption\">Coffee beans - pexels.com</figcaption></figure>\n<p>2.Grind your beans properly. The size of your coffee grounds can greatly affect the flavor of your coffee. A fine grind will give you a strong, concentrated flavor, while a coarser grind will result in a lighter, more mellow brew. Experiment to find the grind size that works best for you and your brewing method.</p><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/01/pexels-los-muertos-crew-7487366-683x1024.jpg\" alt=\"\" class=\"wp-image-15994\"/><figcaption class=\"wp-element-caption\">Coffee Grinder-pexels.com</figcaption></figure>\n<p>3.Use the right amount of coffee. A general rule of thumb is to use about 1 to 2 tablespoons of coffee grounds per 6 ounces of water. Adjust this ratio to your personal taste, but keep in mind that using too much coffee can result in a bitter brew.</p><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2023/01/pexels-lood-goosen-1235706-683x1024.jpg\" alt=\"\" class=\"wp-image-15996\"/><figcaption class=\"wp-element-caption\">Cup Of Coffee-Pexels.com</figcaption></figure>\n<p>4.Water temperature is key. The ideal brewing temperature for coffee is between 195-205 degrees Fahrenheit. If your water is too hot, it can scald the coffee and create a bitter taste. If it\'s not hot enough, it will not extract the full flavor from the beans.</p>\n<p>5.Store your coffee properly. To keep your beans fresh, store them in an airtight container in a cool, dry place. Avoid exposing them to light, moisture, and heat, as these can all affect the flavor of your coffee.</p>', 1, '2023-01-06 14:55:22', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2023/01/photo_2023-01-12_07-39-33.jpg'),
(45, 'A Guide to Growing Healthy Coffee Trees', 'a-guide-to-growing-healthy-coffee-trees', 'Your coffee crop can only be as good as your coffee trees – but growing strong, healthy, and productive plants means paying attention to several critical variables. Whether you’re a producer looking to improve the qualit…', '<p>Your coffee crop can only be as good as your coffee trees – but growing strong, healthy, and productive plants means paying attention to several critical variables. Whether you’re a producer looking to improve the quality and quantity of your cherries, or a roaster/coffee buyer working with producers, it’s important that you know these.</p>\n<p>These are some practices recommended by Fernando Farfan, an agronomist with the Colombian Coffee Growers Federation’s research centre Cenicafé, Read and discover.</p>\n<h2><strong>LOCATION & CLIMATE</strong></h2><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2022/12/coffee_climate-1024x683.jpg\" alt=\"\" class=\"wp-image-15983\"/></figure>\n<p>Fernando\'s first concern is that location is the most important factor since it determines the best production system. “If the climate conditions, precipitation, temperature and sun intensity are of the optimum conditions for coffee farming,” he says, “then the coffee can be grown with complete sun exposure.”</p>\n<p>The best climate conditions for the plant’s development and production are, according to Fernando, temperatures between 21°C and 22°C, 1,800 hours of sunshine annually, and a yearly rainfall between 1,500 and 2,000 mm.</p>\n<p>Where there are temperatures greater than 25°C, more than 1,800 hours of solar brightness per year, little cloudiness, and annual rainfall of less than 1,500 mm, Fernando explains that water deficiency may become an issue.</p><blockquote class=\"wp-block-quote\">\n<p>“This produces adverse conditions for crop development, presenting us with water deficiency, meaning that there is not enough water for the coffee plantation, which affects the productive development of the coffee crop,” he says.</p></blockquote>\n<p>When this is the case, the best option is to grow coffee under shade trees. These will protect the crop from the sun during the dry season and lower temperatures. In Colombia, a significant portion of coffee trees is grown under shade – approximately 40%, according to the Colombian Coffee Growers Federation.</p>\n<h2><strong>SEEDS & SEEDLINGS</strong></h2>\n<p>The next point to consider is what you’re planting. Fernando explains that, when it comes to seeds, traceability is crucial. “[If we don’t have traceability], we don’t know which substrates have been used, what size the bag is, and what the source of that seed is,” he says.</p>\n<p>Seedlings that are grown in the wrong bag size risk poor development and root problems, he advises, recommending 17 cm x 23 cm as the ideal size. And when it comes to the soil, he suggests a substrate that is one-third organic material.</p>\n<p>“This way, a good anchoring of the plant to the soil will be guaranteed, and it will allow a better absorption of the nutrients, better development, and better production,” he emphasises.</p><figure class=\"wp-block-image size-full\"><img src=\"https://gmac.coffee/wp-content/uploads/2022/12/cdca-e1512422458944.jpg\" alt=\"\" class=\"wp-image-15981\"/><figcaption class=\"wp-element-caption\"><em>Coffee flowers blossom while cherries ripen on the branch in Colombia. Credit: Café de Colombia</em></figcaption></figure>\n<h2><strong>PLANTING DENSITY</strong></h2>\n<p>The number of trees you can plant in an area depends on the climate and soil conditions, Fernando says. Direct sun exposure generally allows for 8,000–10,000 plants per hectare. However, if you’re also planting shade trees, you’ll only be able to plant 6,000–8,000 per hectare.</p>\n<p>Other aspects will also affect the planting density, including:</p><ul>\n<li>Variety: If the coffee tree is small or a dwarf plant, such as Caturra or Cenicafé 1, you can plant more per hectare. On the other hand, if it’s a large tree, you will have to sow them with less density.</li>\n<li><strong>Tree layout/spatial arrangement</strong>: The space between the coffee plants and the different paths between rows will affect how many plants you can grow per hectare.</li></ul>\n<p>What’s more, the planting density will affect factors like the crop’s rejuvenation cycle – more on that later!</p>\n<p>Fernando tells us that it’ll often be twenty years until a plot is re-planted, so it’s important to get the location and density right.</p>\n<h2><strong>SOIL MANAGEMENT</strong></h2>\n<p>Soil management includes everything from nutrition and weed management to preventing diseases and fungi.</p>\n<p>Cenicafé has published a guide to soil management <em>(</em><a href=\"http://www.cenicafe.org/es/publications/bot032.pdf\" target=\"_blank\" rel=\"noreferrer noopener\"><em>Fertilidad del suelo y nutición del café en Colombia</em></a><em>)</em> which recommends paying particular attention in the earlier stages. It’s important to prepare the soil before planting the seedling and to maintain it well during the first growing phase, as this will continue to impact the tree throughout its life.</p>\n<p>Fernando tells me that one of the first things that producers should look at is the soil acidity. Too low an acidity (measured as units of Hydrogen potential or pH) signifies high concentration of free hydrogen in the soil, a condition that restricts the roots’ access to water and nutrients. The best soil acidity for coffee growth is between a pH of 5.0 and 5.5.</p>\n<p>Cenicafé’s guide also recommends that coffee trees need nitrogen and phosphorus, as well as increased levels of potassium and magnesium during the reproductive phase (i.e. when the trees flower). Producers who wish to use fertiliser should do so one to two months after planting, and repeat this on average every four months (depending on the soil’s water content).</p>\n<p>Additionally, producers should watch out for weeds – which will compete with the coffee for nutrients and water – and early signs of <a rel=\"noreferrer noopener\" href=\"https://perfectdailygrind.com/2016/08/video-guide-combating-la-broca-coffee-berry-borer/\" target=\"_blank\">the coffee borer beetle</a> and <a rel=\"noreferrer noopener\" href=\"https://perfectdailygrind.com/2017/06/how-is-honduras-responding-to-recent-coffee-leaf-rust-outbreak/\" target=\"_blank\">leaf rust</a>.</p>\n<h2><strong>THE REJUVENATION CYCLE</strong></h2>\n<p>Coffee trees should be periodically <a href=\"https://perfectdailygrind.com/2016/05/origin-insight-prune-stump-coffee-trees-2-videos/\" target=\"_blank\" rel=\"noreferrer noopener\">pruned and stumped</a>. To prune, producers should cut the secondary and tertiary branches from the tree, leaving more space for the primary ones to grow. To stump, they should cut the tree down to just 30 cm in height –  something that requires waiting for the coffee trees to regrow before they can produce cherries again.</p>\n<p>Fernando tells me that the frequency of stumping should be linked to the planting density: if you want to plant more trees per hectare, you’ll need to stump more frequently.</p>\n<p>“If there is a sowing density of 2,500 to 3,000 trees per hectare, the plantation’s production levels will start to decrease after 10 years. If there are 5,000 trees per hectare, then the plantation’s production will decrease after 7 years, and if there are 10,000 trees per hectare, this plantation’s production will decline between 4 to 5 years [after planting],” he explains.</p>\n<p>What’s more, he recommends that rejuvenation should occur after four to five harvests (i.e. five to six years after planting), no matter if the coffee is grown in the shade or with direct sun exposure.</p>\n<p>Producers should carefully balance their planting density, rejuvenation cycles, and shade percentages to find the best system for their crops.   </p><figure class=\"wp-block-image size-large\"><img src=\"https://gmac.coffee/wp-content/uploads/2022/12/coffee_rejuvenation-1024x683.jpg\" alt=\"\" class=\"wp-image-15982\"/><figcaption class=\"wp-element-caption\">Gmac CoffeeTrees: Growing Coffee Blanch</figcaption></figure>\n<p>There are many variables to consider when planting and nurturing coffee trees. What’s more, best practices will vary from one farm to the next as the climate, variety, and soil conditions change. The additional support of an agronomist will always be helpful.</p>\n<p>However, following the steps above can help producers to look after their trees’ health and productivity. Coffee buyers should also be aware of these points so they know what questions to ask during farm visits – and what recommendations to make, should they need to.</p>\n<p>After all, it’s only through growing healthy trees that great coffee can be produced.</p>\n<p>source: </p>\n<p>Perfect Grind Blog</p>', 1, '2022-12-27 08:00:27', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2022/12/healthy_coffee_trees.jpg'),
(46, 'Rwanda Coffee Growing: Everything You Need To Know', 'rwanda-coffee-growing-everything-you-need-to-know', 'At first glance, those Rwanda coffee beans on that shop counter might look like just another bag ‘a beans with a missing vowel in its name. But the history of the Rwandan coffee industry, both tragic and epic, has not on…', '<p>At first glance, those Rwanda coffee beans on that shop counter might look like just another bag ‘a beans with a missing vowel in its name.</p>\n<p>But the history of the Rwandan coffee industry, both tragic and epic, has not only kept coffee production from the Land of a Thousand Hills alive – it’s transformed it into one of the most sought-after coffees in the modern world.</p>\n<h2>A Brief History Of Rwandan Coffee</h2>\n<p>The tiny, landlocked East <a href=\"https://www.homegrounds.co/african-coffee/\">African</a> nation of Rwanda is nestled in the middle of the continent and located not far from Kenya, one of the world’s leading coffee-growing nations.</p>\n<p>The first coffee plants reached Rwanda as late as the beginning of the 20th century, but it was another three decades before Rwanda coffee production began to take off.</p>\n<p>Initially, while the quantity was there, the quality was still lacking. The types of <a href=\"https://www.homegrounds.co/best-coffee-beans-bucket-list/\">coffee beans</a> grown in Rwanda were rather low-grade, particularly due to the harsh demands of the colonial government before the country gained independence in the middle of the century.</p><blockquote class=\"wp-block-quote\">\n<p>Did you now?</p>\n<p>The first coffee plants were brought to Rwanda by German missionairs in the early 1900s, but i took 3 decades before the coffee production took off.</p></blockquote>\n<p>Even after independence, the coffee industry suffered (<a href=\"https://perfectdailygrind.com/2015/04/the-history-of-rwandan-coffee-the-story-behind-epiphanie-muhirwa/\">1</a>) as crises struck both the coffee world (<a rel=\"noreferrer noopener\" href=\"https://www.coffeehabitat.com/2006/02/the_coffee_cris/\" target=\"_blank\">2</a>) and Rwanda (<a rel=\"noreferrer noopener\" href=\"https://www.history.com/this-day-in-history/civil-war-erupts-in-rwanda\" target=\"_blank\">3</a>) in the 1990s, and by the turn of the millennium, the industry was in shambles.</p>\n<p>But the farmers didn’t give up the metaphorical coffee ghost, and instead started turning to the world of high-end coffees. A National Coffee Strategy (<a rel=\"noreferrer noopener\" href=\"https://www.naeb.gov.rw/index.php?id=49\" target=\"_blank\">4</a>) was developed that reinvented their coffee industry.</p>\n<p><em>In the last two decades since, Rwanda has grown into one of the top thirty largest coffee-growing countries in the world.</em></p>\n<p>Rwanda coffee exports now generally figure in the dozens of millions of pounds per year – that is, when production isn’t being tampered with by issues within the country. The bulk of this production comes from small farms rather than larger estates.</p>\n<h2>Growing Coffee In Rwanda</h2><figure class=\"wp-block-image size-full\"><img src=\"https://gmac.coffee/wp-content/uploads/2022/12/Rwandan-Coffee-Growing-Regions-edited.jpg\" alt=\"\" class=\"wp-image-15957\"/><figcaption class=\"wp-element-caption\">Rwanda coffee growing regions.</figcaption></figure>\n<p>Most of the plantations in the country are fairly high, and are usually situated somewhere between 4,000 and 6,500 feet above sea level. This gives the coffee plants a nice, high altitude to grow in that is perfect for producing excellent beans (<a rel=\"noreferrer noopener\" href=\"https://driftaway.coffee/elevation/\" target=\"_blank\">5</a>).</p>\n<p>Of all these farms, 95% have coffee plants that are not just Arabica – they are of the highest quality Rwanda bourbon coffee variety.</p>\n<p>The local growing season typically begins in either September or October and continues until harvesting takes place between March and July. Within those months, the harvesting tends to peak from May on.</p><p id=\"references\"><strong>References</strong></p><ol>\n<li>The History of Rwandan Coffee & The Story Behind Epiphanie Muhirwa | Perfect Daily Grind Retrieved from https://perfectdailygrind.com/2015/04/the-history-of-rwandan-coffee-the-story-behind-epiphanie-muhirwa/</li>\n<li>The Coffee Crisis — Coffee & Conservation Retrieved from https://www.coffeehabitat.com/2006/02/the_coffee_cris/</li>\n<li>Violence erupts in Rwanda, foreshadowing genocide of 800,000 – HISTORY Retrieved from https://www.history.com/this-day-in-history/civil-war-erupts-in-rwanda</li>\n<li>Coffee Strategy Retrieved from https://www.naeb.gov.rw/index.php?id=49 </li>\n<li>Rwanda Coffee https://www.homegrounds.co/rwanda-coffee/</li></ol>', 1, '2022-12-19 19:19:28', '2026-09-24 07:33:02', '2026-09-24 07:33:47', 'https://gmac.coffee/wp-content/uploads/2022/12/photo_2022-12-19_21-16-02.jpg');
