INSERT INTO `products` (`id`, `product_category_id`, `name`, `slug`, `short_description`, `description`, `price`, `features`, `order`, `is_active`, `created_at`, `updated_at`, `barcode`) VALUES
(1, 1, 'Karenge Washed Bourbon', 'karenge-washed-bourbon', 'Bright citrus, black tea, and a clean red-apple finish from our flagship station.', '<p>Our signature fully washed Bourbon from Karenge, Rwamagana. Cherries are hand-sorted, fermented with care, and dried on raised beds until the cup is clean and precise.</p><p>Ideal for roasters who want a transparent Rwandan profile with citrus, black tea, and a long sweet finish.</p>', 18.5, '[\"Altitude 1,650\\u20131,800 masl\",\"Variety Bourbon\",\"Process Fully washed\",\"Cupping 86+\"]', 1, 0, '2026-09-23 13:10:11', '2026-09-23 14:29:08', NULL),
(2, 2, 'Honey Process Lot', 'honey-process-lot', 'Stone fruit and caramel with a silky body, prepared as a yellow honey.', '<p>A selected honey lot with mucilage left on the parchment during drying. The result is a rounder cup: peach, caramel, and cocoa, without losing Rwanda’s signature clarity.</p>', 21, '[\"Process Yellow honey\",\"Notes Peach, caramel, cocoa\",\"Limited seasonal lot\"]', 2, 0, '2026-09-23 13:10:11', '2026-09-23 14:29:08', NULL),
(3, 3, 'Natural Anaerobic', 'natural-anaerobic', 'Tropical fruit and winey depth from a controlled anaerobic natural.', '<p>Whole cherries rest in sealed tanks before drying. Expect tropical fruit, berry jam, and a structured finish — an experimental lot for adventurous roasters.</p>', 24, '[\"Process Anaerobic natural\",\"Notes Tropical fruit, berry\",\"Small experimental lot\"]', 3, 0, '2026-09-23 13:10:11', '2026-09-23 14:29:08', NULL),
(4, 1, 'Women’s Association Lot', 'women-association-lot', 'A fully traceable lot from 156 women farmers in our partner association.', '<p>Separated from the main harvest and processed with extra care. Buying this lot supports women producers who are building quality and income at origin.</p>', 22.5, '[\"156 women farmers\",\"Rainforest Alliance\",\"Fully washed Bourbon\"]', 4, 0, '2026-09-23 13:10:11', '2026-09-23 14:29:08', NULL),
(5, 1, 'Fully Washed AA', 'fully-washed-aa', 'Screen AA, dense beans, classic Rwanda: floral, citrus, and brown sugar.', '<p>A consistent export lot sized for importers who need volume with quality. Clean fermentation, raised-bed drying, and strict defect sorting.</p>', 16, '[\"Grade AA\",\"Floral and citrus\",\"Export ready\"]', 5, 0, '2026-09-23 13:10:11', '2026-09-23 14:29:08', NULL),
(6, 4, 'House Roast', 'house-roast', 'A balanced roast of our washed Bourbon — cocoa, orange, and honey.', '<p>Roasted in small batches from Karenge washed coffee. Easy to brew as filter or espresso, and a clear introduction to the GMAC cup.</p>', 14, '[\"250g bags\",\"Filter or espresso\",\"Notes Cocoa, orange, honey\"]', 6, 0, '2026-09-23 13:10:11', '2026-09-23 14:29:08', NULL),
(7, 5, 'Roasted Coffee 250g — Red & White', 'roasted-coffee-250g-red-white', 'Official roasted bag, 250g red & white pack. Made in Rwanda by Green Mountain Arabica Coffee Ltd.', '<p>Green Mountain Arabica Coffee Ltd is a Rwandan coffee producer and trading company. Packed as a 250g red & white retail bag.</p><p>Republic of Rwanda · Kigali City · Kicukiro District · Niboye Sector</p><p>info@gmac.coffee · www.gmac.coffee · GTIN 0679721369612</p>', 5000, '[\"Net weight 250g\",\"Roasted\",\"Pack red & white\",\"Origin Rwanda\",\"Manufacturer Green Mountain Arabica Coffee Ltd\",\"GTIN 0679721369612\"]', 1, 1, '2026-09-23 14:04:28', '2026-09-23 18:53:55', '0679721369612'),
(8, 5, 'Roasted Coffee 250g — Green & White', 'roasted-coffee-250g-green-white', 'Official roasted bag, 250g green & white pack. Made in Rwanda by Green Mountain Arabica Coffee Ltd.', '<p>Green Mountain Arabica Coffee Ltd is a Rwandan coffee producer and trading company. Packed as a 250g green & white retail bag.</p><p>Republic of Rwanda · Kigali City · Kicukiro District · Niboye Sector</p><p>info@gmac.coffee · www.gmac.coffee · GTIN 0679721369778</p>', 5000, '[\"Net weight 250g\",\"Roasted\",\"Pack green & white\",\"Origin Rwanda\",\"Manufacturer Green Mountain Arabica Coffee Ltd\",\"GTIN 0679721369778\"]', 2, 1, '2026-09-23 14:04:28', '2026-09-23 18:53:55', '0679721369778'),
(9, 5, 'Roasted Coffee 250g — Chocolate & White', 'roasted-coffee-250g-chocolate-white', 'Official roasted bag, 250g chocolate & white pack. Made in Rwanda by Green Mountain Arabica Coffee Ltd.', '<p>Green Mountain Arabica Coffee Ltd is a Rwandan coffee producer and trading company. Packed as a 250g chocolate & white retail bag.</p><p>Republic of Rwanda · Kigali City · Kicukiro District · Niboye Sector</p><p>info@gmac.coffee · www.gmac.coffee · GTIN 0679721369955</p>', 5000, '[\"Net weight 250g\",\"Roasted\",\"Pack chocolate & white\",\"Origin Rwanda\",\"Manufacturer Green Mountain Arabica Coffee Ltd\",\"GTIN 0679721369955\"]', 3, 1, '2026-09-23 14:04:28', '2026-09-23 18:53:55', '0679721369955'),
(10, 6, 'Roasted Coffee 500g — Chocolate & White', 'roasted-coffee-500g-chocolate-white', 'Official roasted bag, 500g chocolate & white pack. Made in Rwanda by Green Mountain Arabica Coffee Ltd.', '<p>Green Mountain Arabica Coffee Ltd is a Rwandan coffee producer and trading company. Packed as a 500g chocolate & white retail bag.</p><p>Republic of Rwanda · Kigali City · Kicukiro District · Niboye Sector</p><p>info@gmac.coffee · www.gmac.coffee · GTIN 0679721369544</p>', 10000, '[\"Net weight 500g\",\"Roasted\",\"Pack chocolate & white\",\"Origin Rwanda\",\"Manufacturer Green Mountain Arabica Coffee Ltd\",\"GTIN 0679721369544\"]', 4, 1, '2026-09-23 14:04:28', '2026-09-23 18:53:55', '0679721369544'),
(11, 6, 'Roasted Coffee 500g — Red & White', 'roasted-coffee-500g-red-white', 'Official roasted bag, 500g red & white pack. Made in Rwanda by Green Mountain Arabica Coffee Ltd.', '<p>Green Mountain Arabica Coffee Ltd is a Rwandan coffee producer and trading company. Packed as a 500g red & white retail bag.</p><p>Republic of Rwanda · Kigali City · Kicukiro District · Niboye Sector</p><p>info@gmac.coffee · www.gmac.coffee · GTIN 0679721369300</p>', 10000, '[\"Net weight 500g\",\"Roasted\",\"Pack red & white\",\"Origin Rwanda\",\"Manufacturer Green Mountain Arabica Coffee Ltd\",\"GTIN 0679721369300\"]', 6, 1, '2026-09-23 14:04:28', '2026-09-23 18:53:55', '0679721369300'),
(12, 6, 'Roasted Coffee 500g — Green & White', 'roasted-coffee-500g-green-white', 'Official roasted bag, 500g green & white pack. Made in Rwanda by Green Mountain Arabica Coffee Ltd.', '<p>Green Mountain Arabica Coffee Ltd is a Rwandan coffee producer and trading company. Packed as a 500g green & white retail bag.</p><p>Republic of Rwanda · Kigali City · Kicukiro District · Niboye Sector</p><p>info@gmac.coffee · www.gmac.coffee · GTIN 0679721369476</p>', 10000, '[\"Net weight 500g\",\"Roasted\",\"Pack green & white\",\"Origin Rwanda\",\"Manufacturer Green Mountain Arabica Coffee Ltd\",\"GTIN 0679721369476\"]', 5, 1, '2026-09-23 14:04:28', '2026-09-23 18:53:55', '0679721369476'),
(13, 7, 'Roasted Coffee 1kg — Chocolate & White', 'roasted-coffee-1kg-chocolate-white', 'Official roasted bag, 1kg chocolate & white pack. Made in Rwanda by Green Mountain Arabica Coffee Ltd.', '<p>Green Mountain Arabica Coffee Ltd is a Rwandan coffee producer and trading company. Packed as a 1kg chocolate & white retail bag.</p><p>Republic of Rwanda · Kigali City · Kicukiro District · Niboye Sector</p><p>info@gmac.coffee · www.gmac.coffee · GTIN 0679721369230</p>', 20000, '[\"Net weight 1kg\",\"Roasted\",\"Pack chocolate & white\",\"Origin Rwanda\",\"Manufacturer Green Mountain Arabica Coffee Ltd\",\"GTIN 0679721369230\"]', 7, 1, '2026-09-23 14:04:28', '2026-09-23 18:53:55', '0679721369230'),
(14, 7, 'Roasted Coffee 1kg — Red & White', 'roasted-coffee-1kg-red-white', 'Official roasted bag, 1kg red & white pack. Made in Rwanda by Green Mountain Arabica Coffee Ltd.', '<p>Green Mountain Arabica Coffee Ltd is a Rwandan coffee producer and trading company. Packed as a 1kg red & white retail bag.</p><p>Republic of Rwanda · Kigali City · Kicukiro District · Niboye Sector</p><p>info@gmac.coffee · www.gmac.coffee · GTIN 0679721369090</p>', 20000, '[\"Net weight 1kg\",\"Roasted\",\"Pack red & white\",\"Origin Rwanda\",\"Manufacturer Green Mountain Arabica Coffee Ltd\",\"GTIN 0679721369090\"]', 9, 1, '2026-09-23 14:04:28', '2026-09-23 18:53:55', '0679721369090'),
