INSERT INTO `team_members` (`id`, `name`, `role`, `bio`, `order`, `is_active`, `created_at`, `updated_at`, `email`, `phone`) VALUES
(1, 'Rukaka Steven', 'Managing Director', 'Steven leads operations, buyer relationships, and the systems that keep lots traceable from Karenge to export.', 2, 1, '2026-09-24 07:10:38', '2026-09-24 08:17:57', 'info@gmac.coffee', '+250 783 053 415'),
(2, 'Habimana Japhet', 'Marketing Manager', 'Japhet looks after the GMAC brand, buyer conversations, and the story that travels with every bag.', 3, 1, '2026-09-24 07:10:38', '2026-09-24 08:40:22', 'japhet@gmac.coffee', NULL),
(3, 'Samuel Niyomuhoza', 'IT', 'Samuel keeps the digital side of GMAC running — the website, systems, and the tools the team uses every day.', 6, 1, '2026-09-24 07:10:38', '2026-09-24 08:17:57', NULL, NULL),
(4, 'David Biziyaremye', 'Production Manager', 'David runs production at the station — cherry in, parchment out, and the lot notes that stay attached.', 4, 1, '2026-09-24 07:10:38', '2026-09-24 08:40:22', 'biziyaremyedavid@gmac.coffee', NULL),
(5, 'Gakenyeye Faustin', 'Finance Officer', 'Faustin looks after the books, payments, and the numbers that keep the stations and the shop honest.', 5, 1, '2026-09-24 07:10:38', '2026-09-24 08:40:22', 'gakenyeyefaustin@gmac.coffee', NULL),
(6, 'Divine Irakoze', 'Finance Assistant', 'Divine supports finance day to day — invoices, records, and the paperwork behind every shipment.', 7, 1, '2026-09-24 07:10:38', '2026-09-24 08:40:22', 'divine@gmac.coffee', NULL),
(7, 'Niyonsaba Jeanne', 'Chairperson & Founder', 'Jeanne founded GMAC Coffee in 2012 and chairs the board — more value from origin, stronger traceability, and a fairer path for the women who grow the coffee.', 1, 1, '2026-09-24 08:17:57', '2026-09-24 08:40:22', 'niyonsabajeanne@gmac.coffee', '+250 783 053 415');
INSERT INTO `testimonials` (`id`, `name`, `role`, `company`, `quote`, `rating`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Clara M.', 'Head of Coffee', 'Nordic Roastery', 'The Karenge washed lot was the cleanest Rwanda we bought last year — citrus, tea, and a finish that held on the bar.', 5, 1, 1, '2026-09-23 13:10:11', '2026-09-23 13:10:11'),
(2, 'James Okafor', 'Green Buyer', 'East & Co.', 'Communication from origin was clear, samples arrived on time, and the women’s lot sold through in two weeks.', 5, 2, 1, '2026-09-23 13:10:11', '2026-09-23 13:10:11'),
(3, 'Hana Saito', 'Importer', 'Pacific Specialty', 'Traceability notes were usable, not decorative. We could tell a real story to our roasters.', 5, 3, 1, '2026-09-23 13:10:11', '2026-09-23 13:10:11');
